321: async function pullOllamaModel(modelName: string) {
322:   const model = modelName.trim();
323:   if (!model) throw new Error('Model name cannot be empty.');
324:   if (currentPullAbort) throw new Error('A model download is already in progress.');
325: 
326:   currentPullAbort = new AbortController();
