329:   try {
330:     const res = await fetch('http://127.0.0.1:11434/api/pull', {
331:       method: 'POST',
332:       headers: { 'Content-Type': 'application/json' },
333:       body: JSON.stringify({ model, stream: true }),
334:       signal: currentPullAbort.signal
335:     });
336: 
337:     if (!res.ok) throw new Error(`Ollama pull failed (${res.status} ${res.statusText})`);
338:     if (!res.body) throw new Error('No response body from Ollama');
339: 
340:     const reader = res.body.getReader();
341:     const decoder = new TextDecoder();
342:     let buffer = '';
343: 
344:     while (true) {
345:       const { value, done } = await reader.read();
346:       if (done) break;
347:       buffer += decoder.decode(value, { stream: true });
348:       const lines = buffer.split('\n');
349:       buffer = lines.pop() || '';
