351:       for (const line of lines) {
352:         if (!line.trim()) continue;
353:         try {
354:           const parsed = JSON.parse(line);
355:           if (parsed.error) throw new Error(parsed.error);
356:           const total = parsed.total || 0;
357:           const completed = parsed.completed || 0;
358:           const percent = total > 0 ? Math.round((completed / total) * 100) : 0;
359:           broadcast('models:pull-progress', {
360:             model,
361:             status: parsed.status || 'Downloading model...',
362:             completed,
363:             total,
364:             percent,
365:             done: parsed.status === 'success'
366:           });
367:         } catch (e: any) {
368:           if (e.message && !e.message.startsWith('Unexpected')) throw e;
369:         }
370:       }
371:     }
372: 
373:     activeLlmModel = model;
374:     await saveIndex();
375:     broadcast('models:pull-progress', { model, status: 'Model ready and activated!', percent: 100, done: true });
376:     return { success: true, activeModel: activeLlmModel };
