export type MemoryType = 'task' | 'decision';
export type MemoryStatus = 'suggested' | 'open' | 'completed' | 'dismissed';

export interface MemoryItem {
  id: string;
  type: MemoryType;
  title: string;
  details?: string;
  sourcePath: string;
  relativePath: string;
  sourceExcerpt: string;
  status: MemoryStatus;
  confidence?: number; // 0.0 to 1.0
  confidenceReason?: string;
  dueDate?: string; // Explicit date string if present in source or provided by user
  createdAt: number;
  updatedAt: number;
  contentHash: string; // Stable deduplication key
  chunkId?: string;
}

export interface ExtractionProgress {
  stage: 'idle' | 'extracting' | 'completed' | 'cancelled' | 'error';
  currentChunk: number;
  totalChunks: number;
  extractedCount: number;
  newCount: number;
  message: string;
  done: boolean;
  error?: string;
}

export interface ExtractionOptions {
  forceAll?: boolean;
  chunkBatchSize?: number;
}

export interface MemoryFilter {
  type?: MemoryType;
  status?: MemoryStatus;
  query?: string;
}

export interface MemorySearchResult {
  item: MemoryItem;
  score: number;
}

import { promises as fs } from 'node:fs';
import { join } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import type { MemoryItem, MemoryFilter, MemoryStatus, MemoryType } from './types.js';

export function createContentHash(
  type: MemoryType,
  sourcePath: string,
  title: string,
  sourceExcerpt: string
): string {
  const normType = type.trim().toLowerCase();
  const normPath = (sourcePath || '').trim().toLowerCase();
  const normTitle = (title || '').trim().toLowerCase().replace(/\s+/g, ' ');
  // Use first 150 chars of normalized excerpt for robust deduplication across slight spacing differences
  const normExcerpt = (sourceExcerpt || '').trim().toLowerCase().replace(/\s+/g, ' ').slice(0, 150);

  return createHash('sha256')
    .update(`${normType}:${normPath}:${normTitle}:${normExcerpt}`)
    .digest('hex');
}

export function isValidMemoryItem(item: any): item is MemoryItem {
  if (!item || typeof item !== 'object') return false;
  if (typeof item.id !== 'string' || !item.id.trim()) return false;
  if (item.type !== 'task' && item.type !== 'decision') return false;
  if (typeof item.title !== 'string' || !item.title.trim()) return false;
  if (typeof item.sourcePath !== 'string') return false;
  if (typeof item.sourceExcerpt !== 'string') return false;
  if (!['suggested', 'open', 'completed', 'dismissed'].includes(item.status)) return false;
  if (typeof item.createdAt !== 'number' || typeof item.updatedAt !== 'number') return false;
  return true;
}

export class MemoryStore {
  private filePath: string;
  private items: Map<string, MemoryItem> = new Map();
  private hashes: Map<string, string> = new Map(); // contentHash -> item.id
  private loaded = false;

  constructor(storageDir: string) {
    this.filePath = join(storageDir, 'memory-items-v1.json');
  }

  public async load(): Promise<void> {
    this.items.clear();
    this.hashes.clear();

    try {
      const raw = await fs.readFile(this.filePath, 'utf8');
      const data = JSON.parse(raw);
      const list = Array.isArray(data) ? data : (Array.isArray(data?.items) ? data.items : []);

      for (const rawItem of list) {
        if (isValidMemoryItem(rawItem)) {
          // Ensure contentHash is present
          const hash = rawItem.contentHash || createContentHash(
            rawItem.type,
            rawItem.sourcePath,
            rawItem.title,
            rawItem.sourceExcerpt
          );
          const item: MemoryItem = { ...rawItem, contentHash: hash };
          this.items.set(item.id, item);
          this.hashes.set(hash, item.id);
        }
      }
    } catch (err: any) {
      if (err.code !== 'ENOENT') {
        console.warn('Failed to load memory store from disk; starting with empty store:', err);
      }
    }

    this.loaded = true;
  }

  public async save(): Promise<void> {
    const list = Array.from(this.items.values());
    const tempFile = `${this.filePath}.tmp.${Date.now()}`;
    const payload = JSON.stringify({ version: 1, items: list }, null, 2);

    await fs.writeFile(tempFile, payload, 'utf8');
    await fs.rename(tempFile, this.filePath);
  }

  public getItems(filter?: MemoryFilter): MemoryItem[] {
    let list = Array.from(this.items.values());

    if (filter) {
      if (filter.type) {
        list = list.filter(i => i.type === filter.type);
      }
      if (filter.status) {
        list = list.filter(i => i.status === filter.status);
      }
      if (filter.query && filter.query.trim()) {
        const q = filter.query.toLowerCase().trim();
        list = list.filter(i =>
          i.title.toLowerCase().includes(q) ||
          (i.details && i.details.toLowerCase().includes(q)) ||
          i.sourceExcerpt.toLowerCase().includes(q) ||
          i.sourcePath.toLowerCase().includes(q)
        );
      }
    }

    // Sort: suggestions & open first, then completed, then dismissed; newest first within status
    const statusOrder: Record<MemoryStatus, number> = {
      suggested: 0,
      open: 1,
      completed: 2,
      dismissed: 3
    };

    return list.sort((a, b) => {
      const orderDiff = statusOrder[a.status] - statusOrder[b.status];
      if (orderDiff !== 0) return orderDiff;
      return b.updatedAt - a.updatedAt;
    });
  }

  public getItem(id: string): MemoryItem | null {
    return this.items.get(id) || null;
  }

  public findByHash(hash: string): MemoryItem | null {
    const id = this.hashes.get(hash);
    if (!id) return null;
    return this.items.get(id) || null;
  }

  public async addSuggestions(
    candidates: Array<{
      type: MemoryType;
      title: string;
      details?: string;
      sourcePath: string;
      relativePath?: string;
      sourceExcerpt: string;
      confidence?: number;
      confidenceReason?: string;
      dueDate?: string;
      chunkId?: string;
    }>
  ): Promise<MemoryItem[]> {
    const added: MemoryItem[] = [];
    const now = Date.now();

    for (const c of candidates) {
      if (!c.title || !c.title.trim()) continue;
      if (!c.sourceExcerpt || !c.sourceExcerpt.trim()) continue;
      if (c.type !== 'task' && c.type !== 'decision') continue;

      const hash = createContentHash(c.type, c.sourcePath, c.title, c.sourceExcerpt);

      // Duplicate prevention: if already exists (suggested, open, completed, or dismissed), do not re-add
      if (this.hashes.has(hash)) {
        continue;
      }

      // Also check if an item with the same normalized title and source file already exists
      const existingSameTitle = Array.from(this.items.values()).find(
        existing =>
          existing.type === c.type &&
          existing.sourcePath === c.sourcePath &&
          existing.title.trim().toLowerCase() === c.title.trim().toLowerCase()
      );
      if (existingSameTitle) {
        continue;
      }

      const item: MemoryItem = {
        id: randomUUID(),
        type: c.type,
        title: c.title.trim(),
        details: c.details ? c.details.trim() : undefined,
        sourcePath: c.sourcePath,
        relativePath: c.relativePath || '',
        sourceExcerpt: c.sourceExcerpt.trim(),
        status: 'suggested',
        confidence: typeof c.confidence === 'number' ? Math.max(0, Math.min(1, c.confidence)) : 0.8,
        confidenceReason: c.confidenceReason?.trim(),
        dueDate: c.dueDate?.trim() || undefined,
        createdAt: now,
        updatedAt: now,
        contentHash: hash,
        chunkId: c.chunkId
      };

      this.items.set(item.id, item);
      this.hashes.set(hash, item.id);
      added.push(item);
    }

    if (added.length > 0) {
      await this.save();
    }

    return added;
  }

  public async confirmItem(id: string): Promise<MemoryItem> {
    const item = this.items.get(id);
    if (!item) throw new Error(`Memory item not found: ${id}`);
    if (item.status !== 'suggested') {
      throw new Error(`Cannot confirm item with status: ${item.status}`);
    }

    item.status = 'open';
    item.updatedAt = Date.now();
    await this.save();
    return item;
  }

  public async updateItem(
    id: string,
    updates: {
      title?: string;
      details?: string;
      dueDate?: string;
      status?: MemoryStatus;
    }
  ): Promise<MemoryItem> {
    const item = this.items.get(id);
    if (!item) throw new Error(`Memory item not found: ${id}`);

    if (updates.title !== undefined) {
      const trimmed = updates.title.trim();
      if (!trimmed) throw new Error('Title cannot be empty');
      item.title = trimmed;
    }

    if (updates.details !== undefined) {
      item.details = updates.details.trim() || undefined;
    }

    if (updates.dueDate !== undefined) {
      item.dueDate = updates.dueDate.trim() || undefined;
    }

    if (updates.status !== undefined) {
      if (!['suggested', 'open', 'completed', 'dismissed'].includes(updates.status)) {
        throw new Error(`Invalid status: ${updates.status}`);
      }
      item.status = updates.status;
    }

    item.updatedAt = Date.now();
    await this.save();
    return item;
  }

  public async dismissItem(id: string): Promise<MemoryItem> {
    const item = this.items.get(id);
    if (!item) throw new Error(`Memory item not found: ${id}`);

    item.status = 'dismissed';
    item.updatedAt = Date.now();
    await this.save();
    return item;
  }

  public async completeItem(id: string): Promise<MemoryItem> {
    const item = this.items.get(id);
    if (!item) throw new Error(`Memory item not found: ${id}`);
    if (item.type !== 'task') {
      throw new Error('Only tasks can be marked as completed.');
    }

    item.status = 'completed';
    item.updatedAt = Date.now();
    await this.save();
    return item;
  }

  public async reopenItem(id: string): Promise<MemoryItem> {
    const item = this.items.get(id);
    if (!item) throw new Error(`Memory item not found: ${id}`);

    item.status = 'open';
    item.updatedAt = Date.now();
    await this.save();
    return item;
  }

  public async deleteItem(id: string): Promise<boolean> {
    const item = this.items.get(id);
    if (!item) return false;

    this.items.delete(id);
    this.hashes.delete(item.contentHash);
    await this.save();
    return true;
  }

  public async createManualItem(data: {
    type: MemoryType;
    title: string;
    details?: string;
    sourcePath?: string;
    relativePath?: string;
    sourceExcerpt?: string;
    dueDate?: string;
    status?: MemoryStatus;
  }): Promise<MemoryItem> {
    const title = (data.title || '').trim();
    if (!title) throw new Error('Title cannot be empty');
    if (data.type !== 'task' && data.type !== 'decision') {
      throw new Error('Type must be task or decision');
    }

    const sourcePath = data.sourcePath || 'Manual entry';
    const sourceExcerpt = data.sourceExcerpt || title;
    const hash = createContentHash(data.type, sourcePath, title, sourceExcerpt);
    const now = Date.now();

    const item: MemoryItem = {
      id: randomUUID(),
      type: data.type,
      title,
      details: data.details ? data.details.trim() : undefined,
      sourcePath,
      relativePath: data.relativePath || '',
      sourceExcerpt,
      status: data.status || 'open',
      confidence: 1.0,
      confidenceReason: 'Manually entered by user',
      dueDate: data.dueDate?.trim() || undefined,
      createdAt: now,
      updatedAt: now,
      contentHash: hash
    };

    this.items.set(item.id, item);
    this.hashes.set(hash, item.id);
    await this.save();
    return item;
  }

  public async clear(): Promise<void> {
    this.items.clear();
    this.hashes.clear();
    await this.save();
  }
}

import type { Chunk } from '../index.js';
import type { MemoryItem, MemoryType, ExtractionProgress, ExtractionOptions } from './types.js';
import { MemoryStore } from './store.js';

interface RawExtractedItem {
  type?: string;
  title?: string;
  details?: string;
  excerpt?: string;
  confidence?: number;
  confidenceReason?: string;
  dueDate?: string | null;
}

export function verifyExcerptInChunk(excerpt: string, chunkText: string): boolean {
  if (!excerpt || !chunkText) return false;
  const cleanExcerpt = excerpt.trim().toLowerCase().replace(/\s+/g, ' ');
  const cleanChunk = chunkText.toLowerCase().replace(/\s+/g, ' ');

  // Direct substring match
  if (cleanChunk.includes(cleanExcerpt)) return true;

  // Partial match: first 40 chars of excerpt
  const startPiece = cleanExcerpt.slice(0, Math.min(cleanExcerpt.length, 45));
  if (startPiece.length >= 15 && cleanChunk.includes(startPiece)) return true;

  // Word token overlap check
  const excerptWords = cleanExcerpt.match(/[a-z0-9_-]{3,}/g) || [];
  if (excerptWords.length < 3) return false;

  let matchedWords = 0;
  for (const w of excerptWords) {
    if (cleanChunk.includes(w)) matchedWords++;
  }
  return (matchedWords / excerptWords.length) >= 0.75;
}

export function extractHeuristicCandidates(chunk: { path: string; relativePath?: string; text: string; id: string }): Array<{
  type: MemoryType;
  title: string;
  details?: string;
  sourcePath: string;
  relativePath?: string;
  sourceExcerpt: string;
  confidence: number;
  confidenceReason: string;
  dueDate?: string;
  chunkId: string;
}> {
  const results: Array<{
    type: MemoryType;
    title: string;
    details?: string;
    sourcePath: string;
    relativePath?: string;
    sourceExcerpt: string;
    confidence: number;
    confidenceReason: string;
    dueDate?: string;
    chunkId: string;
  }> = [];

  const lines = chunk.text.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line || line.length < 10) continue;

    // Check for Tasks: TODO, FIXME, [ ] unchecked markdown boxes, "Action Item:"
    const taskMatch = line.match(/^(?:[-*]\s*\[\s*\]|\/\/\s*TODO:?|#\s*TODO:?|TODO:?|FIXME:?|ACTION(?:\s+ITEM)?:?)\s*(.+)$/i);
    if (taskMatch && taskMatch[1]) {
      const taskBody = taskMatch[1].trim();
      if (taskBody.length >= 6 && !taskBody.toLowerCase().startsWith('example')) {
        // Check for explicit deadline in the task body (e.g., "by Friday", "before Dec 15", "due: 2026-10-20")
        const dueMatch = taskBody.match(/(?:due(?::|\s+on|\s+by)?|by|before)\s+([A-Za-z0-9, -]{3,20})/i);
        const dueDate = dueMatch ? dueMatch[1].trim() : undefined;

        results.push({
          type: 'task',
          title: taskBody.slice(0, 120),
          details: lines.slice(Math.max(0, i - 1), Math.min(lines.length, i + 3)).join('\n').trim(),
          sourcePath: chunk.path,
          relativePath: chunk.relativePath,
          sourceExcerpt: line,
          confidence: 0.85,
          confidenceReason: 'Explicit task marker found in source document',
          dueDate,
          chunkId: chunk.id
        });
        continue;
      }
    }

    // Check for Decisions: "Decision:", "Decided to", "Architecture Decision:", "We chose to", "We agreed to"
    const decisionMatch = line.match(/^(?:(?:###?\s*)?Decision:?|ADR:?|Resolution:?|Decided(?:\s+to)?|We decided to|We agreed to|Chosen approach:?)\s*(.+)$/i);
    if (decisionMatch && decisionMatch[1]) {
      const decBody = decisionMatch[1].trim();
      if (decBody.length >= 10 && !decBody.toLowerCase().includes('?')) {
        results.push({
          type: 'decision',
          title: decBody.slice(0, 140),
          details: lines.slice(Math.max(0, i - 1), Math.min(lines.length, i + 4)).join('\n').trim(),
          sourcePath: chunk.path,
          relativePath: chunk.relativePath,
          sourceExcerpt: line,
          confidence: 0.85,
          confidenceReason: 'Explicit decision header or statement found in source document',
          chunkId: chunk.id
        });
      }
    }
  }

  return results;
}

export class MemoryExtractor {
  private abortController: AbortController | null = null;
  private isRunning = false;

  public get running(): boolean {
    return this.isRunning;
  }

  public cancel(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
    this.isRunning = false;
  }

  public async extractFromChunks(
    chunks: Array<{ id: string; path: string; relativePath: string; name: string; text: string }>,
    store: MemoryStore,
    options: {
      activeModel: string;
      onProgress?: (p: ExtractionProgress) => void;
      forceAll?: boolean;
    }
  ): Promise<{ extractedCount: number; newCount: number; totalProcessed: number }> {
    if (this.isRunning) {
      throw new Error('Extraction is already in progress.');
    }

    this.isRunning = true;
    this.abortController = new AbortController();
    const signal = this.abortController.signal;

    let totalExtracted = 0;
    let totalNew = 0;

    // Filter relevant chunks to avoid wasting inference on binary or empty text
    const eligibleChunks = chunks.filter(c => {
      if (!c.text || c.text.length < 40) return false;
      return true;
    });

    const totalChunks = eligibleChunks.length;
    let processed = 0;

    const reportProgress = (stage: ExtractionProgress['stage'], msg: string, done = false, error?: string) => {
      options.onProgress?.({
        stage,
        currentChunk: processed,
        totalChunks,
        extractedCount: totalExtracted,
        newCount: totalNew,
        message: msg,
        done,
        error
      });
    };

    reportProgress('extracting', `Starting extraction across ${totalChunks} passages...`);

    try {
      // First check if Ollama is accessible
      let ollamaOnline = false;
      try {
        const pingRes = await fetch('http://127.0.0.1:11434/api/tags', { signal });
        if (pingRes.ok) ollamaOnline = true;
      } catch {
        ollamaOnline = false;
      }

      for (let i = 0; i < eligibleChunks.length; i++) {
        if (signal.aborted) {
          reportProgress('cancelled', 'Extraction cancelled by user.', true);
          return { extractedCount: totalExtracted, newCount: totalNew, totalProcessed: processed };
        }

        const chunk = eligibleChunks[i];
        processed = i + 1;

        // Run heuristic extraction first
        const heuristics = extractHeuristicCandidates(chunk);
        if (heuristics.length > 0) {
          const added = await store.addSuggestions(heuristics);
          totalExtracted += heuristics.length;
          totalNew += added.length;
        }

        // If Ollama is available, run LLM-powered extraction
        if (ollamaOnline) {
          try {
            const llmCandidates = await this.extractWithOllama(chunk, options.activeModel, signal);
            if (llmCandidates.length > 0) {
              const added = await store.addSuggestions(llmCandidates);
              totalExtracted += llmCandidates.length;
              totalNew += added.length;
            }
          } catch (err: any) {
            if (err.name === 'AbortError') {
              reportProgress('cancelled', 'Extraction cancelled by user.', true);
              return { extractedCount: totalExtracted, newCount: totalNew, totalProcessed: processed };
            }
            console.warn(`Ollama extraction error on chunk ${chunk.name}:`, err.message);
          }
        }

        if (processed % 2 === 0 || processed === totalChunks) {
          reportProgress(
            'extracting',
            `Analyzed ${processed}/${totalChunks} passages (${totalNew} new candidate items found)`
          );
        }
      }

      const finalMsg = ollamaOnline
        ? `Extraction complete. Analyzed ${totalChunks} passages. Found ${totalNew} new candidate items.`
        : `Extraction complete using local heuristic analysis (${totalChunks} passages analyzed, ${totalNew} candidates found). Note: Start Ollama for deep semantic extraction.`;

      reportProgress('completed', finalMsg, true);
      return { extractedCount: totalExtracted, newCount: totalNew, totalProcessed: processed };
    } catch (err: any) {
      const errorMsg = err.name === 'AbortError' ? 'Extraction cancelled.' : err.message || String(err);
      reportProgress(err.name === 'AbortError' ? 'cancelled' : 'error', errorMsg, true, errorMsg);
      throw err;
    } finally {
      this.isRunning = false;
      this.abortController = null;
    }
  }

  private async extractWithOllama(
    chunk: { id: string; path: string; relativePath: string; name: string; text: string },
    model: string,
    signal: AbortSignal
  ): Promise<Array<{
    type: MemoryType;
    title: string;
    details?: string;
    sourcePath: string;
    relativePath?: string;
    sourceExcerpt: string;
    confidence: number;
    confidenceReason: string;
    dueDate?: string;
    chunkId: string;
  }>> {
    // Quick heuristic filter: check if the text contains any task or decision indicators
    const lower = chunk.text.toLowerCase();
    const hasIndicators =
      lower.includes('todo') ||
      lower.includes('fixme') ||
      lower.includes('decision') ||
      lower.includes('decide') ||
      lower.includes('agreed') ||
      lower.includes('will use') ||
      lower.includes('chose') ||
      lower.includes('plan') ||
      lower.includes('finish') ||
      lower.includes('implement') ||
      lower.includes('before') ||
      lower.includes('deadline') ||
      lower.includes('must') ||
      lower.includes('need to') ||
      lower.includes('architecture') ||
      lower.includes('database') ||
      lower.includes('migration') ||
      lower.includes('refactor');

    // If chunk has no potential keywords and is code, skip to preserve inference speed
    if (!hasIndicators && chunk.name.match(/\.(js|jsx|ts|tsx|py|rs|go|java|c|h|cpp|sql|sh)$/i)) {
      return [];
    }

    const prompt = [
      'You are a precise technical memory assistant for OpenSearch / RecallDesk.',
      'Analyze the following document passage and extract any UNFINISHED TASKS or CONFIRMED ARCHITECTURAL/PRODUCT DECISIONS.',
      '',
      'CRITICAL RULES:',
      '1. Only extract items that have explicit factual evidence in the text.',
      '2. Do NOT invent deadlines, commitments, or decisions.',
      '3. Do NOT extract hypothetical examples (e.g., "for example, if you use Postgres...").',
      '4. Do NOT extract third-party library documentation or code instructions.',
      '5. Do NOT extract open/unresolved questions as confirmed decisions.',
      '6. For each item, excerpt MUST be an EXACT VERBATIM quote from the PASSAGE.',
      '7. If no clear tasks or decisions exist, return {"items": []}.',
      '',
      'Respond ONLY with a JSON object in this exact schema:',
      '{',
      '  "items": [',
      '    {',
      '      "type": "task" | "decision",',
      '      "title": "Concise title describing the task or decision (max 15 words)",',
      '      "details": "Brief supporting context or rationale from text",',
      '      "excerpt": "Exact verbatim quote from the passage supporting this item",',
      '      "confidence": 0.85,',
      '      "dueDate": "Explicit deadline mentioned in text, or null"',
      '    }',
      '  ]',
      '}',
      '',
      `PASSAGE (from ${chunk.relativePath || chunk.name}):`,
      '"""',
      chunk.text.slice(0, 1100),
      '"""',
      'JSON Output:'
    ].join('\n');

    const timeout = setTimeout(() => {
      // local chunk timeout
    }, 25_000);

    try {
      const res = await fetch('http://127.0.0.1:11434/api/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: model || 'smollm2:360m-instruct-q4_0',
          prompt,
          stream: false,
          format: 'json',
          options: {
            temperature: 0.1,
            num_predict: 350
          }
        }),
        signal
      });

      if (!res.ok) return [];

      const data = await res.json() as { response?: string };
      if (!data.response?.trim()) return [];

      let parsed: { items?: RawExtractedItem[] };
      try {
        parsed = JSON.parse(data.response.trim());
      } catch {
        // Attempt to find JSON object substring
        const match = data.response.match(/\{[\s\S]*\}/);
        if (match) {
          parsed = JSON.parse(match[0]);
        } else {
          return [];
        }
      }

      if (!Array.isArray(parsed?.items)) return [];

      const verifiedCandidates: Array<{
        type: MemoryType;
        title: string;
        details?: string;
        sourcePath: string;
        relativePath?: string;
        sourceExcerpt: string;
        confidence: number;
        confidenceReason: string;
        dueDate?: string;
        chunkId: string;
      }> = [];

      for (const item of parsed.items) {
        if (!item.title || !item.excerpt) continue;
        const type: MemoryType = item.type === 'decision' ? 'decision' : 'task';

        // Discard hypothetical phrasing or false positives
        const lowerTitle = item.title.toLowerCase();
        if (
          lowerTitle.startsWith('example') ||
          lowerTitle.startsWith('how to') ||
          lowerTitle.startsWith('documentation') ||
          lowerTitle.includes('hypothetical')
        ) {
          continue;
        }

        // Verify excerpt exists in chunk text
        if (!verifyExcerptInChunk(item.excerpt, chunk.text)) {
          continue;
        }

        const confidence = typeof item.confidence === 'number'
          ? Math.max(0.5, Math.min(1.0, item.confidence))
          : 0.8;

        verifiedCandidates.push({
          type,
          title: item.title.trim(),
          details: item.details?.trim() || undefined,
          sourcePath: chunk.path,
          relativePath: chunk.relativePath,
          sourceExcerpt: item.excerpt.trim(),
          confidence,
          confidenceReason: `Extracted via local LLM with verified passage excerpt`,
          dueDate: (item.dueDate && item.dueDate !== 'null') ? String(item.dueDate).trim() : undefined,
          chunkId: chunk.id
        });
      }

      return verifiedCandidates;
    } finally {
      clearTimeout(timeout);
    }
  }
}

import { ipcMain, shell } from 'electron';
import { existsSync } from 'node:fs';
import { MemoryStore } from './store.js';
import { MemoryExtractor } from './extractor.js';
import type { MemoryFilter, MemoryItem, MemorySearchResult, MemoryStatus, MemoryType } from './types.js';

export * from './types.js';
export * from './store.js';
export * from './extractor.js';

function words(s: string) {
  return [...new Set(s.toLowerCase().match(/[a-z0-9_./-]{2,}/g) || [])];
}

function lexicalScore(query: string, text: string) {
  const q = words(query);
  const t = text.toLowerCase();
  if (!q.length) return 0;
  let score = 0;
  for (const w of q) {
    if (t.includes(w)) score += 1;
  }
  return score / q.length;
}

export function searchMemoryItems(
  items: MemoryItem[],
  query: string,
  options?: { includeSuggested?: boolean; status?: MemoryStatus; type?: MemoryType }
): MemorySearchResult[] {
  if (!query || !query.trim()) {
    return [];
  }

  let candidates = items;
  if (!options?.includeSuggested) {
    // Only search confirmed/active memory items (open, completed) unless explicitly requested
    candidates = candidates.filter(i => i.status === 'open' || i.status === 'completed');
  } else {
    candidates = candidates.filter(i => i.status !== 'dismissed');
  }

  if (options?.status) {
    candidates = candidates.filter(i => i.status === options.status);
  }
  if (options?.type) {
    candidates = candidates.filter(i => i.type === options.type);
  }

  const scored: MemorySearchResult[] = [];

  for (const item of candidates) {
    const searchableText = `${item.title} ${item.details || ''} ${item.sourceExcerpt} ${item.sourcePath} ${item.type}`;
    const score = lexicalScore(query, searchableText);
    if (score > 0) {
      scored.push({ item, score });
    }
  }

  return scored.sort((a, b) => b.score - a.score);
}

export class MemoryController {
  private store: MemoryStore;
  private extractor: MemoryExtractor;

  constructor(
    storageDir: string,
    private getChunks: () => Array<{ id: string; path: string; relativePath: string; name: string; text: string }>,
    private getActiveModel: () => string,
    private broadcast: (channel: string, payload: unknown) => void
  ) {
    this.store = new MemoryStore(storageDir);
    this.extractor = new MemoryExtractor();
  }

  public async init(): Promise<void> {
    await this.store.load();
    this.registerIpcHandlers();
  }

  public getStore(): MemoryStore {
    return this.store;
  }

  public getExtractor(): MemoryExtractor {
    return this.extractor;
  }

  public registerIpcHandlers(): void {
    ipcMain.handle('memory:list', async (_event, filter?: MemoryFilter) => {
      // Validate filter inputs
      if (filter && typeof filter !== 'object') {
        throw new Error('Invalid filter format.');
      }
      return this.store.getItems(filter);
    });

    ipcMain.handle('memory:extract', async () => {
      if (this.extractor.running) {
        throw new Error('Task & decision extraction is already running.');
      }

      const chunks = this.getChunks();
      if (!chunks.length) {
        throw new Error('No indexed files found. Index at least one folder before extracting tasks and decisions.');
      }

      return this.extractor.extractFromChunks(chunks, this.store, {
        activeModel: this.getActiveModel(),
        onProgress: p => {
          this.broadcast('memory:extraction-progress', p);
        }
      });
    });

    ipcMain.handle('memory:cancel-extract', async () => {
      this.extractor.cancel();
      return true;
    });

    ipcMain.handle('memory:confirm', async (_event, id: string) => {
      if (typeof id !== 'string' || !id.trim()) {
        throw new Error('Invalid item ID.');
      }
      return this.store.confirmItem(id.trim());
    });

    ipcMain.handle('memory:update', async (_event, payload: {
      id: string;
      updates: { title?: string; details?: string; dueDate?: string; status?: MemoryStatus };
    }) => {
      if (!payload || typeof payload !== 'object' || typeof payload.id !== 'string') {
        throw new Error('Invalid update parameters.');
      }
      return this.store.updateItem(payload.id.trim(), payload.updates || {});
    });

    ipcMain.handle('memory:dismiss', async (_event, id: string) => {
      if (typeof id !== 'string' || !id.trim()) {
        throw new Error('Invalid item ID.');
      }
      return this.store.dismissItem(id.trim());
    });

    ipcMain.handle('memory:complete', async (_event, id: string) => {
      if (typeof id !== 'string' || !id.trim()) {
        throw new Error('Invalid item ID.');
      }
      return this.store.completeItem(id.trim());
    });

    ipcMain.handle('memory:reopen', async (_event, id: string) => {
      if (typeof id !== 'string' || !id.trim()) {
        throw new Error('Invalid item ID.');
      }
      return this.store.reopenItem(id.trim());
    });

    ipcMain.handle('memory:delete', async (_event, id: string) => {
      if (typeof id !== 'string' || !id.trim()) {
        throw new Error('Invalid item ID.');
      }
      return this.store.deleteItem(id.trim());
    });

    ipcMain.handle('memory:create', async (_event, payload: {
      type: MemoryType;
      title: string;
      details?: string;
      sourcePath?: string;
      relativePath?: string;
      sourceExcerpt?: string;
      dueDate?: string;
      status?: MemoryStatus;
    }) => {
      if (!payload || typeof payload !== 'object') {
        throw new Error('Invalid creation parameters.');
      }
      return this.store.createManualItem(payload);
    });

    ipcMain.handle('memory:search', async (_event, query: string, options?: { includeSuggested?: boolean }) => {
      if (typeof query !== 'string') {
        throw new Error('Query must be a string.');
      }
      const allItems = this.store.getItems();
      return searchMemoryItems(allItems, query, options);
    });

    ipcMain.handle('memory:open-source', async (_event, filePath: string) => {
      if (typeof filePath !== 'string' || !filePath.trim()) {
        throw new Error('Invalid file path.');
      }
      if (!existsSync(filePath)) {
        throw new Error(`File does not exist on disk: ${filePath}. It may have been moved, renamed, or deleted.`);
      }
      return shell.openPath(filePath);
    });
  }
}

