                            <button
                              className="primary-btn"
                              onClick={() => handlePullModel(m.id)}
                              disabled={isPulling || !!pullingModel || !modelsData?.ollamaRunning}
                            >
                              <Download size={13}/> {isPulling ? "Downloading…" : "Download in App"}
                            </button>
                          )}
