import test from 'node:test';
import assert from 'node:assert/strict';
import { promises as fs } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { randomUUID } from 'node:crypto';
import { MemoryStore, createContentHash } from '../src/main/memory/store.ts';

test('MemoryStore: saves and loads items across restarts (persistence)', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store1 = new MemoryStore(testDir);
    await store1.load();

    await store1.addSuggestions([
      {
        type: 'task',
        title: 'Finish the authentication flow before Friday',
        details: 'Need OAuth2 token refresh logic',
        sourcePath: '/docs/auth.md',
        sourceExcerpt: 'TODO: Finish the authentication flow before Friday',
        confidence: 0.9,
        dueDate: 'before Friday'
      },
      {
        type: 'decision',
        title: 'Use PostgreSQL instead of MongoDB for the production database',
        details: 'Relational integrity needed for financial records',
        sourcePath: '/docs/architecture.md',
        sourceExcerpt: 'Decision: Use PostgreSQL instead of MongoDB for the production database',
        confidence: 0.95
      }
    ]);

    const items1 = store1.getItems();
    assert.strictEqual(items1.length, 2);

    // Simulate restart with a new store instance pointing to same file
    const store2 = new MemoryStore(testDir);
    await store2.load();
    const items2 = store2.getItems();

    assert.strictEqual(items2.length, 2);
    assert.strictEqual(items2[0].status, 'suggested');
    assert.strictEqual(items2[1].status, 'suggested');

    const authTask = items2.find(i => i.title.includes('authentication'));
    assert.ok(authTask);
    assert.strictEqual(authTask.dueDate, 'before Friday');
    assert.strictEqual(authTask.sourcePath, '/docs/auth.md');
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

test('MemoryStore: duplicate prevention across repeated extraction', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    const candidate = {
      type: 'task' as const,
      title: 'Add retry handling to the API client',
      details: 'Exponential backoff with jitter',
      sourcePath: '/src/client.ts',
      sourceExcerpt: '// TODO: Add retry handling to the API client',
      confidence: 0.85
    };

    // First addition
    const added1 = await store.addSuggestions([candidate]);
    assert.strictEqual(added1.length, 1);
    assert.strictEqual(store.getItems().length, 1);

    // Repeated extraction with exact same candidate
    const added2 = await store.addSuggestions([candidate]);
    assert.strictEqual(added2.length, 0, 'Should not add duplicate item');
    assert.strictEqual(store.getItems().length, 1);

    // Even if user confirmed the item, repeated extraction must NOT re-suggest
    await store.confirmItem(added1[0].id);
    const added3 = await store.addSuggestions([candidate]);
    assert.strictEqual(added3.length, 0, 'Should not re-suggest confirmed item');

    // Even if user dismissed the item, repeated extraction must NOT re-suggest
    await store.dismissItem(added1[0].id);
    const added4 = await store.addSuggestions([candidate]);
    assert.strictEqual(added4.length, 0, 'Should not re-suggest dismissed item');
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

test('MemoryStore: status lifecycle (confirm, edit, dismiss, complete, reopen)', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    const [item] = await store.addSuggestions([
      {
        type: 'task',
        title: 'Fix the failing integration tests',
        sourcePath: '/tests/suite.ts',
        sourceExcerpt: '// TODO: Fix the failing integration tests',
        confidence: 0.88
      }
    ]);

    assert.strictEqual(item.status, 'suggested');

    // 1. Confirm
    const confirmed = await store.confirmItem(item.id);
    assert.strictEqual(confirmed.status, 'open');

    // 2. Edit
    const updated = await store.updateItem(item.id, {
      title: 'Fix failing auth integration tests on CI',
      details: 'Mock server token expired',
      dueDate: '2026-10-25'
    });
    assert.strictEqual(updated.title, 'Fix failing auth integration tests on CI');
    assert.strictEqual(updated.details, 'Mock server token expired');
    assert.strictEqual(updated.dueDate, '2026-10-25');

    // 3. Complete
    const completed = await store.completeItem(item.id);
    assert.strictEqual(completed.status, 'completed');

    // 4. Reopen
    const reopened = await store.reopenItem(item.id);
    assert.strictEqual(reopened.status, 'open');

    // 5. Dismiss
    const dismissed = await store.dismissItem(item.id);
    assert.strictEqual(dismissed.status, 'dismissed');

    // 6. Delete
    const deleted = await store.deleteItem(item.id);
    assert.strictEqual(deleted, true);
    assert.strictEqual(store.getItem(item.id), null);
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

test('MemoryStore: validation and error handling', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    // Non-existent ID errors
    await assert.rejects(
      async () => store.confirmItem('non-existent-id'),
      /Memory item not found/
    );

    // Empty title update error
    const [task] = await store.addSuggestions([
      {
        type: 'task',
        title: 'Valid title',
        sourcePath: '/file.ts',
        sourceExcerpt: 'TODO: Valid title'
      }
    ]);

    await assert.rejects(
      async () => store.updateItem(task.id, { title: '   ' }),
      /Title cannot be empty/
    );

    // Completing a decision should be rejected (decisions are adopted or dismissed, tasks are completed)
    const [decision] = await store.addSuggestions([
      {
        type: 'decision',
        title: 'Keep embeddings local',
        sourcePath: '/docs/adr.md',
        sourceExcerpt: 'Decision: Keep embeddings local'
      }
    ]);
    await store.confirmItem(decision.id);

    await assert.rejects(
      async () => store.completeItem(decision.id),
      /Only tasks can be marked as completed/
    );
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { promises as fs } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { randomUUID } from 'node:crypto';
import {
  extractHeuristicCandidates,
  verifyExcerptInChunk,
  MemoryExtractor
} from '../src/main/memory/extractor.ts';
import { MemoryStore } from '../src/main/memory/store.ts';

test('MemoryExtractor: extracts valid tasks and deadlines from text', () => {
  const chunk = {
    id: 'c1',
    path: '/project/docs/auth.md',
    relativePath: 'docs/auth.md',
    text: [
      '# Authentication Architecture',
      'The new OAuth provider requires refresh tokens.',
      'TODO: Finish the authentication flow before Friday',
      '- [ ] Add retry handling to the API client',
      'Everything else is complete.'
    ].join('\n')
  };

  const extracted = extractHeuristicCandidates(chunk);
  assert.strictEqual(extracted.length, 2);

  const task1 = extracted.find(e => e.title.includes('authentication flow'));
  assert.ok(task1);
  assert.strictEqual(task1.type, 'task');
  assert.strictEqual(task1.dueDate, 'Friday');
  assert.strictEqual(task1.sourceExcerpt, 'TODO: Finish the authentication flow before Friday');

  const task2 = extracted.find(e => e.title.includes('retry handling'));
  assert.ok(task2);
  assert.strictEqual(task2.type, 'task');
  assert.strictEqual(task2.sourceExcerpt, '- [ ] Add retry handling to the API client');
});

test('MemoryExtractor: extracts valid decisions and distinguishes from hypotheticals', () => {
  const chunk = {
    id: 'c2',
    path: '/project/docs/database.md',
    relativePath: 'docs/database.md',
    text: [
      '# Architecture Decisions',
      'Decision: Use PostgreSQL instead of MongoDB for the production database',
      'We evaluated MongoDB and DynamoDB, but relational constraints and ACID transactions are required.',
      'We decided to keep embeddings and document indexing local',
      'Hypothetical example: For example, should we use Redis? We have not decided yet.'
    ].join('\n')
  };

  const extracted = extractHeuristicCandidates(chunk);
  assert.strictEqual(extracted.length, 2);

  const dec1 = extracted.find(e => e.title.includes('PostgreSQL'));
  assert.ok(dec1);
  assert.strictEqual(dec1.type, 'decision');
  assert.strictEqual(dec1.sourceExcerpt, 'Decision: Use PostgreSQL instead of MongoDB for the production database');

  const dec2 = extracted.find(e => e.title.includes('keep embeddings'));
  assert.ok(dec2);
  assert.strictEqual(dec2.type, 'decision');

  // Ensure hypothetical questions are not extracted
  const hypothetical = extracted.find(e => e.title.toLowerCase().includes('redis'));
  assert.strictEqual(hypothetical, undefined);
});

test('MemoryExtractor: verifyExcerptInChunk validates ground truth against source text', () => {
  const chunkText = 'We decided to use SQLite for lightweight local persistence and fast startup.';

  // Exact match
  assert.strictEqual(
    verifyExcerptInChunk('We decided to use SQLite for lightweight local persistence', chunkText),
    true
  );

  // Case/whitespace normalization
  assert.strictEqual(
    verifyExcerptInChunk('  we decided to USE sqlite for lightweight   ', chunkText),
    true
  );

  // Hallucinated excerpt not in text
  assert.strictEqual(
    verifyExcerptInChunk('We will migrate everything to AWS DynamoDB next week', chunkText),
    false
  );

  // Empty inputs
  assert.strictEqual(verifyExcerptInChunk('', chunkText), false);
  assert.strictEqual(verifyExcerptInChunk('some text', ''), false);
});

test('MemoryExtractor: handles empty index and short/unsupported passages gracefully', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    const extractor = new MemoryExtractor();
    const emptyChunks: any[] = [];

    const result = await extractor.extractFromChunks(emptyChunks, store, {
      activeModel: 'test-model'
    });

    assert.strictEqual(result.extractedCount, 0);
    assert.strictEqual(result.newCount, 0);
    assert.strictEqual(result.totalProcessed, 0);
    assert.strictEqual(store.getItems().length, 0);
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

test('MemoryExtractor: runs gracefully when Ollama is unavailable without crashing', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    const extractor = new MemoryExtractor();
    const chunks = [
      {
        id: 'c-test',
        path: '/test/notes.md',
        relativePath: 'notes.md',
        name: 'notes.md',
        text: 'TODO: Fix the failing integration tests\nDecision: Keep embeddings local'
      }
    ];

    let progressCalled = false;
    const result = await extractor.extractFromChunks(chunks, store, {
      activeModel: 'non-existent-model',
      onProgress: p => {
        progressCalled = true;
      }
    });

    assert.ok(progressCalled);
    assert.strictEqual(result.totalProcessed, 1);
    // Extracted candidates via robust local heuristics even when Ollama is offline!
    assert.strictEqual(result.newCount, 2);

    const items = store.getItems();
    assert.strictEqual(items.length, 2);
    assert.ok(items.some(i => i.type === 'task' && i.title.includes('integration tests')));
    assert.ok(items.some(i => i.type === 'decision' && i.title.includes('embeddings local')));
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

test('MemoryExtractor: cancellation terminates extraction loop cleanly', async () => {
  const testDir = join(tmpdir(), `recall-desk-test-${randomUUID()}`);
  await fs.mkdir(testDir, { recursive: true });

  try {
    const store = new MemoryStore(testDir);
    await store.load();

    const extractor = new MemoryExtractor();
    const chunks = Array.from({ length: 50 }, (_, i) => ({
      id: `chunk-${i}`,
      path: `/test/file-${i}.md`,
      relativePath: `file-${i}.md`,
      name: `file-${i}.md`,
      text: `TODO: Task number ${i} in document`
    }));

    // Trigger cancel after first chunk
    const extractPromise = extractor.extractFromChunks(chunks, store, {
      activeModel: 'test-model',
      onProgress: p => {
        if (p.currentChunk >= 2) {
          extractor.cancel();
        }
      }
    });

    const res = await extractPromise;
    assert.strictEqual(extractor.running, false);
    assert.ok(res.totalProcessed < 50, 'Should have stopped before finishing all 50 chunks');
  } finally {
    await fs.rm(testDir, { recursive: true, force: true });
  }
});

