export type SourceType =
  | 'text'
  | 'markdown'
  | 'code'
  | 'pdf'
  | 'image'
  | 'folder'
  | 'indexed'
  | 'unsupported';

export type AnalysisGoal =
  | 'overview'
  | 'next_actions'
  | 'tasks'
  | 'decisions'
  | 'issues'
  | 'images'
  | 'custom';

export type EvidenceClassification =
  | 'explicitly_stated'
  | 'directly_observed'
  | 'inferred'
  | 'suggested';

export type FindingType =
  | 'task'
  | 'decision'
  | 'issue'
  | 'recommendation'
  | 'question'
  | 'overview';

export type FindingStatus = 'suggested' | 'accepted' | 'dismissed';

export interface SourceItem {
  id: string;
  path: string;
  name: string;
  type: SourceType;
  sizeBytes: number;
  sizeFormatted: string;
  isFolder?: boolean;
  isIndexed?: boolean;
  status: 'ready' | 'error' | 'unsupported';
  warning?: string;
}

export interface EvidenceLocation {
  lineStart?: number;
  lineEnd?: number;
  page?: number;
  region?: string;
}

export interface IngestedSource {
  id: string;
  originalPath: string;
  relativePath: string;
  displayName: string;
  sourceType: SourceType;
  mimeType: string;
  sizeBytes: number;
  extractedText: string;
  metadata: {
    lineCount?: number;
    pageCount?: number;
    extension?: string;
    hasImages?: boolean;
    imageDimensions?: { width: number; height: number };
    [key: string]: any;
  };
  evidenceLocations: EvidenceLocation[];
  status: 'ready' | 'error' | 'unsupported';
  error?: string;
  unsupportedReason?: string;
  imageDataBase64?: string; // If image source
}

export interface Finding {
  id: string;
  type: FindingType;
  title: string;
  description: string;
  reason?: string;
  sourcePath: string;
  sourceName: string;
  sourceExcerpt: string;
  evidenceClassification: EvidenceClassification;
  confidence?: number; // 0.0 - 1.0
  evidenceLocation?: EvidenceLocation;
  status: FindingStatus;
  targetMemoryType?: 'task' | 'decision';
  dueDate?: string;
  createdAt: number;
  updatedAt: number;
}

export interface IntelligenceAnalysisResult {
  overview: string;
  goal: AnalysisGoal;
  customInstructions?: string;
  findings: Finding[];
  sourcesAnalyzed: {
    total: number;
    successful: number;
    failed: number;
    unsupported: number;
    details: Array<{ path: string; name: string; type: SourceType; status: string }>;
  };
  warnings: string[];
  modelUsed: string;
  completedAt: number;
}

export interface IntelligenceProgress {
  stage: 'inspecting' | 'ingesting' | 'analyzing' | 'completed' | 'cancelled' | 'error';
  percent: number;
  currentSource?: string;
  sourcesProcessed: number;
  totalSources: number;
  findingsCount: number;
  message: string;
  done: boolean;
  error?: string;
}

export interface IntelligenceRunOptions {
  sources: Array<{ path: string; isFolder?: boolean; isIndexed?: boolean }>;
  goal: AnalysisGoal;
  customInstructions?: string;
}

import { promises as fs, existsSync, statSync } from 'node:fs';
import { extname, basename, join, resolve, relative } from 'node:path';
import { randomUUID } from 'node:crypto';
import { PDFParse } from 'pdf-parse';
import type { IngestedSource, SourceItem, SourceType } from './types.ts';

const MAX_FILE_BYTES = 20_000_000; // 20 MB max
const SKIP_DIRS = new Set([
  'node_modules', '.git', 'dist', 'build', 'out', '.next', '.venv',
  'venv', '__pycache__', '.cache', 'vendor', 'target'
]);

export function formatBytes(bytes: number): string {
  if (!bytes || bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
}

export function detectSourceType(filePath: string): { type: SourceType; mimeType: string; isSupported: boolean; reason?: string } {
  const ext = extname(filePath).toLowerCase();

  // Markdown
  if (['.md', '.mdx'].includes(ext)) {
    return { type: 'markdown', mimeType: 'text/markdown', isSupported: true };
  }

  // Plain Text & Config
  if (['.txt', '.log', '.env.example', '.ini', '.toml', '.yaml', '.yml'].includes(ext)) {
    return { type: 'text', mimeType: 'text/plain', isSupported: true };
  }

  // Code & Structured Data
  if (['.json', '.js', '.jsx', '.ts', '.tsx', '.py', '.html', '.css', '.scss', '.sh', '.sql', '.rs', '.go', '.java', '.c', '.h', '.cpp'].includes(ext)) {
    return { type: 'code', mimeType: 'text/plain', isSupported: true };
  }

  // PDF Documents
  if (ext === '.pdf') {
    return { type: 'pdf', mimeType: 'application/pdf', isSupported: true };
  }

  // Screenshots & Images
  if (['.png', '.jpg', '.jpeg', '.webp', '.bmp', '.svg', '.gif'].includes(ext)) {
    const mime = ext === '.png' ? 'image/png' : ext === '.webp' ? 'image/webp' : ext === '.svg' ? 'image/svg+xml' : 'image/jpeg';
    return { type: 'image', mimeType: mime, isSupported: true };
  }

  // Known unsupported binaries or archives
  if (['.zip', '.tar', '.gz', '.7z', '.rar'].includes(ext)) {
    return {
      type: 'unsupported',
      mimeType: 'application/zip',
      isSupported: false,
      reason: `Archive format (${ext}) is not supported for direct reading. Unpack the files first.`
    };
  }

  if (['.exe', '.dll', '.bin', '.dmg', '.iso', '.so', '.dylib'].includes(ext)) {
    return {
      type: 'unsupported',
      mimeType: 'application/octet-stream',
      isSupported: false,
      reason: `Binary executable format (${ext}) cannot be analyzed for project intelligence.`
    };
  }

  if (['.docx', '.xlsx', '.pptx'].includes(ext)) {
    return {
      type: 'unsupported',
      mimeType: 'application/octet-stream',
      isSupported: false,
      reason: `Office binary format (${ext}) is not yet supported. Convert to PDF or Markdown.`
    };
  }

  if (['.mp4', '.mov', '.avi', '.mp3', '.wav', '.m4a'].includes(ext)) {
    return {
      type: 'unsupported',
      mimeType: 'media/unknown',
      isSupported: false,
      reason: `Media file format (${ext}) is not supported for document intelligence.`
    };
  }

  return {
    type: 'unsupported',
    mimeType: 'application/octet-stream',
    isSupported: false,
    reason: `Unrecognized file format (${ext || 'no extension'}). Supported formats include text, Markdown, code, PDF, and screenshots.`
  };
}

export async function inspectSourceItem(targetPath: string): Promise<SourceItem> {
  const safePath = resolve(targetPath);
  if (!existsSync(safePath)) {
    return {
      id: randomUUID(),
      path: targetPath,
      name: basename(targetPath),
      type: 'unsupported',
      sizeBytes: 0,
      sizeFormatted: '0 B',
      status: 'error',
      warning: 'File or folder does not exist on disk.'
    };
  }

  try {
    const stat = await fs.stat(safePath);
    if (stat.isDirectory()) {
      return {
        id: randomUUID(),
        path: safePath,
        name: basename(safePath),
        type: 'folder',
        isFolder: true,
        sizeBytes: 0,
        sizeFormatted: 'Folder',
        status: 'ready'
      };
    }

    const { type, isSupported, reason } = detectSourceType(safePath);
    const sizeBytes = stat.size;
    const sizeFormatted = formatBytes(sizeBytes);

    if (sizeBytes > MAX_FILE_BYTES) {
      return {
        id: randomUUID(),
        path: safePath,
        name: basename(safePath),
        type: 'unsupported',
        sizeBytes,
        sizeFormatted,
        status: 'unsupported',
        warning: `File size (${sizeFormatted}) exceeds 20 MB limit.`
      };
    }

    if (!isSupported) {
      return {
        id: randomUUID(),
        path: safePath,
        name: basename(safePath),
        type,
        sizeBytes,
        sizeFormatted,
        status: 'unsupported',
        warning: reason
      };
    }

    return {
      id: randomUUID(),
      path: safePath,
      name: basename(safePath),
      type,
      sizeBytes,
      sizeFormatted,
      status: 'ready'
    };
  } catch (err: any) {
    return {
      id: randomUUID(),
      path: safePath,
      name: basename(safePath),
      type: 'unsupported',
      sizeBytes: 0,
      sizeFormatted: '0 B',
      status: 'error',
      warning: `Cannot read source: ${err.message || String(err)}`
    };
  }
}

export async function ingestFileSource(filePath: string, relativeRoot?: string): Promise<IngestedSource> {
  const safePath = resolve(filePath);
  const name = basename(safePath);
  const rel = relativeRoot ? relative(relativeRoot, safePath) : name;
  const { type, mimeType, isSupported, reason } = detectSourceType(safePath);

  if (!isSupported) {
    return {
      id: randomUUID(),
      originalPath: safePath,
      relativePath: rel,
      displayName: name,
      sourceType: type,
      mimeType,
      sizeBytes: 0,
      extractedText: '',
      metadata: { extension: extname(safePath) },
      evidenceLocations: [],
      status: 'unsupported',
      unsupportedReason: reason
    };
  }

  try {
    const stat = await fs.stat(safePath);
    if (stat.size > MAX_FILE_BYTES) {
      return {
        id: randomUUID(),
        originalPath: safePath,
        relativePath: rel,
        displayName: name,
        sourceType: 'unsupported',
        mimeType,
        sizeBytes: stat.size,
        extractedText: '',
        metadata: { extension: extname(safePath) },
        evidenceLocations: [],
        status: 'unsupported',
        unsupportedReason: `File size (${formatBytes(stat.size)}) exceeds maximum 20MB limit.`
      };
    }

    // PDF Adapter
    if (type === 'pdf') {
      let parser: any = null;
      try {
        const data = await fs.readFile(safePath);
        parser = new PDFParse({ data });
        const res = await parser.getText();
        const text = res?.text ? res.text.trim() : '';
        const lines = text.split('\n');

        return {
          id: randomUUID(),
          originalPath: safePath,
          relativePath: rel,
          displayName: name,
          sourceType: 'pdf',
          mimeType,
          sizeBytes: stat.size,
          extractedText: text,
          metadata: {
            pageCount: res?.numpages || 1,
            lineCount: lines.length,
            extension: '.pdf'
          },
          evidenceLocations: [{ page: 1, lineStart: 1, lineEnd: lines.length }],
          status: 'ready'
        };
      } catch (e: any) {
        return {
          id: randomUUID(),
          originalPath: safePath,
          relativePath: rel,
          displayName: name,
          sourceType: 'pdf',
          mimeType,
          sizeBytes: stat.size,
          extractedText: '',
          metadata: { extension: '.pdf' },
          evidenceLocations: [],
          status: 'error',
          error: `Failed to parse PDF document: ${e.message || String(e)}`
        };
      } finally {
        if (parser?.destroy) await parser.destroy().catch(() => {});
      }
    }

    // Image / Screenshot Adapter
    if (type === 'image') {
      const data = await fs.readFile(safePath);
      const base64 = data.toString('base64');

      return {
        id: randomUUID(),
        originalPath: safePath,
        relativePath: rel,
        displayName: name,
        sourceType: 'image',
        mimeType,
        sizeBytes: stat.size,
        extractedText: `[Image / Screenshot: ${name}] (Size: ${formatBytes(stat.size)})`,
        imageDataBase64: base64,
        metadata: {
          extension: extname(safePath),
          isVisual: true
        },
        evidenceLocations: [],
        status: 'ready'
      };
    }

    // Text, Markdown, and Code Adapter
    const rawBuffer = await fs.readFile(safePath);
    // Check for null bytes indicative of non-text binary
    if (rawBuffer.subarray(0, Math.min(rawBuffer.length, 8000)).includes(0)) {
      return {
        id: randomUUID(),
        originalPath: safePath,
        relativePath: rel,
        displayName: name,
        sourceType: 'unsupported',
        mimeType: 'application/octet-stream',
        sizeBytes: stat.size,
        extractedText: '',
        metadata: { extension: extname(safePath) },
        evidenceLocations: [],
        status: 'unsupported',
        unsupportedReason: 'Binary file detected (contains null bytes).'
      };
    }

    const text = rawBuffer.toString('utf8');
    const lines = text.split('\n');

    return {
      id: randomUUID(),
      originalPath: safePath,
      relativePath: rel,
      displayName: name,
      sourceType: type,
      mimeType,
      sizeBytes: stat.size,
      extractedText: text,
      metadata: {
        lineCount: lines.length,
        extension: extname(safePath)
      },
      evidenceLocations: [{ lineStart: 1, lineEnd: lines.length }],
      status: 'ready'
    };
  } catch (err: any) {
    return {
      id: randomUUID(),
      originalPath: safePath,
      relativePath: rel,
      displayName: name,
      sourceType: type,
      mimeType,
      sizeBytes: 0,
      extractedText: '',
      metadata: { extension: extname(safePath) },
      evidenceLocations: [],
      status: 'error',
      error: `Failed to read file: ${err.message || String(err)}`
    };
  }
}

export async function ingestFolderSource(
  folderPath: string,
  onProgress?: (processed: number, file: string) => void
): Promise<IngestedSource[]> {
  const safeRoot = resolve(folderPath);
  const results: IngestedSource[] = [];
  const stack = [safeRoot];
  let processed = 0;
  const MAX_FOLDER_FILES = 400; // Limit to 400 files per single folder analysis to maintain responsiveness

  while (stack.length > 0 && results.length < MAX_FOLDER_FILES) {
    const current = stack.pop()!;
    let entries;
    try {
      entries = await fs.readdir(current, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const entry of entries) {
      if (results.length >= MAX_FOLDER_FILES) break;
      if (entry.name.startsWith('.') && ['.git', '.next', '.cache', '.venv'].includes(entry.name)) continue;

      const full = join(current, entry.name);
      if (entry.isSymbolicLink()) continue;

      if (entry.isDirectory()) {
        if (!SKIP_DIRS.has(entry.name)) {
          stack.push(full);
        }
      } else if (entry.isFile()) {
        const { isSupported } = detectSourceType(full);
        if (isSupported) {
          const item = await ingestFileSource(full, safeRoot);
          results.push(item);
          processed++;
          onProgress?.(processed, entry.name);
        }
      }
    }
  }

  return results;
}

import { randomUUID } from 'node:crypto';
import type {
  AnalysisGoal,
  EvidenceClassification,
  Finding,
  FindingType,
  IngestedSource,
  IntelligenceAnalysisResult,
  IntelligenceProgress,
  IntelligenceRunOptions
} from './types.ts';
import {
  detectSourceType,
  ingestFileSource,
  ingestFolderSource
} from './adapters.ts';
import { verifyExcerptInChunk, extractHeuristicCandidates } from '../memory/extractor.ts';

const VISION_MODEL_KEYWORDS = ['vision', 'llava', 'vl', 'minicpm', 'moondream', 'bakllava', 'clip'];

export function isVisionCapable(modelName: string): boolean {
  const lower = (modelName || '').toLowerCase();
  return VISION_MODEL_KEYWORDS.some(kw => lower.includes(kw));
}

export class ProjectIntelligenceAnalyzer {
  private abortController: AbortController | null = null;
  private isRunning = false;

  public get running(): boolean {
    return this.isRunning;
  }

  public cancel(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
    this.isRunning = false;
  }

  public async runAnalysis(
    options: IntelligenceRunOptions,
    context: {
      activeModel: string;
      indexedChunks?: Array<{ id: string; path: string; relativePath: string; name: string; text: string }>;
      onProgress?: (progress: IntelligenceProgress) => void;
    }
  ): Promise<IntelligenceAnalysisResult> {
    if (this.isRunning) {
      throw new Error('Project Intelligence analysis is already running.');
    }

    this.isRunning = true;
    this.abortController = new AbortController();
    const signal = this.abortController.signal;

    const warnings: string[] = [];
    const ingestedSources: IngestedSource[] = [];

    const reportProgress = (
      stage: IntelligenceProgress['stage'],
      percent: number,
      msg: string,
      sourcesProcessed: number,
      totalSources: number,
      findingsCount: number,
      done = false,
      error?: string
    ) => {
      context.onProgress?.({
        stage,
        percent,
        sourcesProcessed,
        totalSources,
        findingsCount,
        message: msg,
        done,
        error
      });
    };

    try {
      reportProgress('inspecting', 5, 'Inspecting and ingesting selected sources...', 0, options.sources.length, 0);

      // Phase 1: Ingestion through source adapters
      for (let i = 0; i < options.sources.length; i++) {
        if (signal.aborted) throw new Error('Analysis cancelled by user.');

        const src = options.sources[i];

        if (src.isIndexed) {
          // Pull from currently indexed chunks
          const chunks = context.indexedChunks || [];
          if (!chunks.length) {
            warnings.push('Indexed content was selected, but no indexed files were found in the current library.');
          } else {
            // Group chunks by file path
            const byFile = new Map<string, string[]>();
            for (const c of chunks) {
              const existing = byFile.get(c.path) || [];
              existing.push(c.text);
              byFile.set(c.path, existing);
            }
            for (const [path, texts] of byFile.entries()) {
              const fullText = texts.join('\n\n');
              const { type, mimeType } = detectSourceType(path);
              ingestedSources.push({
                id: randomUUID(),
                originalPath: path,
                relativePath: path.split(/[/\\]/).pop() || path,
                displayName: path.split(/[/\\]/).pop() || path,
                sourceType: type,
                mimeType,
                sizeBytes: fullText.length,
                extractedText: fullText,
                metadata: { source: 'indexed_library' },
                evidenceLocations: [],
                status: 'ready'
              });
            }
          }
        } else if (src.isFolder) {
          reportProgress('ingesting', 15, `Reading folder: ${src.path.split(/[/\\]/).pop()}...`, i, options.sources.length, 0);
          const folderSources = await ingestFolderSource(src.path, (count, name) => {
            reportProgress('ingesting', Math.min(35, 15 + count), `Ingesting ${name}...`, i, options.sources.length, 0);
          });
          ingestedSources.push(...folderSources);
        } else {
          const single = await ingestFileSource(src.path);
          ingestedSources.push(single);
        }
      }

      const readySources = ingestedSources.filter(s => s.status === 'ready' && s.extractedText.trim().length > 0);
      const unsupportedSources = ingestedSources.filter(s => s.status === 'unsupported');
      const errorSources = ingestedSources.filter(s => s.status === 'error');

      for (const un of unsupportedSources) {
        warnings.push(`Skipped "${un.displayName}": ${un.unsupportedReason || 'Unsupported format.'}`);
      }
      for (const err of errorSources) {
        warnings.push(`Error reading "${err.displayName}": ${err.error || 'Failed to read file.'}`);
      }

      if (!readySources.length) {
        throw new Error('None of the selected sources could be parsed or contained readable text.');
      }

      // Check vision capability if images were supplied
      const imageSources = readySources.filter(s => s.sourceType === 'image');
      const hasVisionModel = isVisionCapable(context.activeModel);

      if (imageSources.length > 0 && !hasVisionModel) {
        warnings.push(
          `Image understanding note: Selected model '${context.activeModel}' is text-only. Visual inspection of diagrams/screenshots requires a vision model (e.g. 'llava' or 'llama3.2-vision'). Image filenames and metadata were recorded.`
        );
      }

      reportProgress(
        'analyzing',
        40,
        `Analyzing ${readySources.length} prepared sources for goal: ${options.goal.replace('_', ' ')}...`,
        readySources.length,
        readySources.length,
        0
      );

      // Phase 2: Call Ollama with strict structured JSON prompt
      let ollamaOnline = false;
      try {
        const pingRes = await fetch('http://127.0.0.1:11434/api/tags', { signal });
        if (pingRes.ok) ollamaOnline = true;
      } catch {
        ollamaOnline = false;
      }

      let analysisResult: { overview: string; findings: Finding[] };

      if (ollamaOnline) {
        try {
          analysisResult = await this.analyzeWithOllama(
            readySources,
            options.goal,
            options.customInstructions,
            context.activeModel,
            imageSources,
            hasVisionModel,
            signal
          );
        } catch (err: any) {
          if (err.name === 'AbortError') throw err;
          console.warn('Ollama analysis failed; falling back to rule-based intelligence engine:', err.message);
          warnings.push(`Local LLM notice: ${err.message}. Applied local rule-based intelligence analysis.`);
          analysisResult = this.analyzeWithHeuristics(readySources, options.goal, options.customInstructions);
        }
      } else {
        warnings.push('Ollama is currently offline on 127.0.0.1:11434. Used local privacy-first rule-based intelligence engine.');
        analysisResult = this.analyzeWithHeuristics(readySources, options.goal, options.customInstructions);
      }

      // Phase 3: Validate and ground findings against ingested text
      const validatedFindings: Finding[] = [];
      const seenTitles = new Set<string>();

      for (const raw of analysisResult.findings) {
        if (!raw.title || !raw.title.trim()) continue;
        const normKey = `${raw.type}:${raw.title.trim().toLowerCase()}`;
        if (seenTitles.has(normKey)) continue;
        seenTitles.add(normKey);

        // Find matching source
        let matchedSource = readySources.find(
          s => s.displayName.toLowerCase() === (raw.sourceName || '').toLowerCase() ||
               s.originalPath.toLowerCase() === (raw.sourcePath || '').toLowerCase()
        );

        if (!matchedSource && readySources.length > 0) {
          // Fallback to source that contains the excerpt
          matchedSource = readySources.find(s => s.extractedText.includes((raw.sourceExcerpt || '').slice(0, 40))) || readySources[0];
        }

        const sourcePath = matchedSource ? matchedSource.originalPath : (raw.sourcePath || 'Unknown');
        const sourceName = matchedSource ? matchedSource.displayName : (raw.sourceName || 'Unknown');
        const sourceExcerpt = (raw.sourceExcerpt || '').trim();

        // Excerpt ground-truth verification
        let evidenceClass = raw.evidenceClassification || 'inferred';
        if (matchedSource && sourceExcerpt) {
          const verified = verifyExcerptInChunk(sourceExcerpt, matchedSource.extractedText);
          if (verified) {
            evidenceClass = 'explicitly_stated';
          } else if (evidenceClass === 'explicitly_stated') {
            evidenceClass = 'inferred';
          }
        }

        const finding: Finding = {
          id: randomUUID(),
          type: raw.type || 'task',
          title: raw.title.trim(),
          description: raw.description?.trim() || raw.title.trim(),
          reason: raw.reason?.trim() || undefined,
          sourcePath,
          sourceName,
          sourceExcerpt: sourceExcerpt || (matchedSource ? matchedSource.extractedText.slice(0, 150) : ''),
          evidenceClassification: evidenceClass,
          confidence: typeof raw.confidence === 'number' ? Math.max(0, Math.min(1, raw.confidence)) : 0.85,
          status: 'suggested',
          targetMemoryType: raw.type === 'decision' ? 'decision' : 'task',
          dueDate: raw.dueDate ? String(raw.dueDate).trim() : undefined,
          createdAt: Date.now(),
          updatedAt: Date.now()
        };

        validatedFindings.push(finding);
      }

      reportProgress('completed', 100, `Completed analysis. Found ${validatedFindings.length} intelligence findings.`, readySources.length, readySources.length, validatedFindings.length, true);

      return {
        overview: analysisResult.overview || 'Analysis completed across selected context sources.',
        goal: options.goal,
        customInstructions: options.customInstructions,
        findings: validatedFindings,
        sourcesAnalyzed: {
          total: ingestedSources.length,
          successful: readySources.length,
          failed: errorSources.length,
          unsupported: unsupportedSources.length,
          details: ingestedSources.map(s => ({
            path: s.originalPath,
            name: s.displayName,
            type: s.sourceType,
            status: s.status
          }))
        },
        warnings,
        modelUsed: ollamaOnline ? context.activeModel : 'Local Heuristic Engine',
        completedAt: Date.now()
      };
    } catch (err: any) {
      const isAbort = err.name === 'AbortError' || (err.message && err.message.includes('cancelled'));
      reportProgress(isAbort ? 'cancelled' : 'error', 0, isAbort ? 'Analysis cancelled.' : err.message, 0, 0, 0, true, err.message);
      throw err;
    } finally {
      this.isRunning = false;
      this.abortController = null;
    }
  }

  private async analyzeWithOllama(
    sources: IngestedSource[],
    goal: AnalysisGoal,
    customInstructions: string | undefined,
    model: string,
    imageSources: IngestedSource[],
    hasVisionModel: boolean,
    signal: AbortSignal
  ): Promise<{ overview: string; findings: Finding[] }> {
    // Build context summary with manageable length
    let contextPassages = '';
    let remainingBudget = 9000; // Character budget for prompt context to avoid small model context overflows

    for (const src of sources) {
      if (remainingBudget <= 0) break;
      const snippet = src.extractedText.slice(0, Math.min(src.extractedText.length, 1800));
      contextPassages += `\n--- SOURCE: ${src.displayName} (Path: ${src.originalPath}, Type: ${src.sourceType}) ---\n${snippet}\n`;
      remainingBudget -= snippet.length;
    }

    const goalDescriptions: Record<AnalysisGoal, string> = {
      overview: 'Provide a structured executive summary of what this project contains, its primary purpose, core components, architecture, and current state.',
      next_actions: 'Analyze the material to determine: What am I working on, what matters most, and what concrete steps should I do next? Identify actionable next steps backed by evidence.',
      tasks: 'Extract all explicit tasks, commitments, acceptance criteria, action items, and TODOs from the files. Highlight any explicit deadlines.',
      decisions: 'Identify all confirmed decisions, architectural choices, technology adoptions, and unresolved questions that need confirmation.',
      issues: 'Identify potential issues, inconsistencies, bugs, risks, or incomplete requirements. Do NOT claim defects unless grounded in the text.',
      images: 'Interpret visible diagrams, screenshots, interface states, or error messages from the provided context.',
      custom: customInstructions ? `User custom instructions: ${customInstructions}` : 'Analyze project context thoroughly.'
    };

    const prompt = [
      'You are RecallDesk Universal Project Intelligence, an expert, privacy-first technical assistant.',
      `ANALYSIS GOAL: ${goalDescriptions[goal]}`,
      customInstructions ? `ADDITIONAL USER INSTRUCTIONS: ${customInstructions}` : '',
      '',
      'GROUNDING AND INTEGRITY RULES:',
      '1. Base every finding strictly on the provided source passages.',
      '2. Do NOT invent deadlines, commitments, or imaginary bug defects.',
      '3. For each finding, provide an exact quote or close substring in "sourceExcerpt".',
      '4. Distinguish explicitly stated items from inferred recommendations using "evidenceClassification".',
      '5. Output MUST be valid JSON adhering strictly to the schema below.',
      '',
      'OUTPUT SCHEMA (JSON only, no markdown wrapping, no extra keys):',
      '{',
      '  "overview": "Comprehensive 2-4 sentence executive synthesis of project status and findings",',
      '  "findings": [',
      '    {',
      '      "type": "task" | "decision" | "issue" | "recommendation" | "question",',
      '      "title": "Concise, descriptive title (under 14 words)",',
      '      "description": "Clear explanation of the finding",',
      '      "reason": "Why this matters or its impact",',
      '      "sourceName": "Exact filename from which this comes",',
      '      "sourceExcerpt": "Verbatim supporting quote from the source passage",',
      '      "evidenceClassification": "explicitly_stated" | "directly_observed" | "inferred" | "suggested",',
      '      "confidence": 0.85,',
      '      "dueDate": "Explicit deadline if present in text, else null"',
      '    }',
      '  ]',
      '}',
      '',
      'CONTEXT PASSAGES:',
      contextPassages,
      '',
      'JSON Output:'
    ].join('\n');

    const requestBody: any = {
      model,
      prompt,
      stream: false,
      format: 'json',
      options: {
        temperature: 0.1,
        num_predict: 850
      }
    };

    // If vision model and images are present, attach images array
    if (hasVisionModel && imageSources.length > 0) {
      const base64Images = imageSources
        .map(img => img.imageDataBase64)
        .filter((b): b is string => typeof b === 'string' && b.length > 0)
        .slice(0, 3);
      if (base64Images.length > 0) {
        requestBody.images = base64Images;
      }
    }

    const res = await fetch('http://127.0.0.1:11434/api/generate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody),
      signal
    });

    if (!res.ok) {
      throw new Error(`Ollama returned status HTTP ${res.status}: ${res.statusText}`);
    }

    const data = await res.json() as { response?: string };
    if (!data.response?.trim()) {
      throw new Error('Ollama returned an empty response.');
    }

    let parsed: any;
    try {
      parsed = JSON.parse(data.response.trim());
    } catch {
      const jsonMatch = data.response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        parsed = JSON.parse(jsonMatch[0]);
      } else {
        throw new Error('Model did not return valid JSON output.');
      }
    }

    return {
      overview: parsed?.overview || 'Project intelligence synthesis completed.',
      findings: Array.isArray(parsed?.findings) ? parsed.findings : []
    };
  }

  private analyzeWithHeuristics(
    sources: IngestedSource[],
    goal: AnalysisGoal,
    customInstructions?: string
  ): { overview: string; findings: Finding[] } {
    const findings: Finding[] = [];
    const sourceNames = sources.map(s => s.displayName).join(', ');

    // Extract heuristics from all sources
    for (const src of sources) {
      const heuristics = extractHeuristicCandidates({
        id: src.id,
        path: src.originalPath,
        relativePath: src.relativePath,
        text: src.extractedText
      });

      for (const h of heuristics) {
        findings.push({
          id: randomUUID(),
          type: h.type,
          title: h.title,
          description: h.details || h.title,
          sourcePath: src.originalPath,
          sourceName: src.displayName,
          sourceExcerpt: h.sourceExcerpt,
          evidenceClassification: 'explicitly_stated',
          confidence: h.confidence,
          status: 'suggested',
          targetMemoryType: h.type,
          dueDate: h.dueDate,
          createdAt: Date.now(),
          updatedAt: Date.now()
        });
      }
    }

    // Add goal-directed recommendations
    if (goal === 'next_actions' || goal === 'overview') {
      const totalLines = sources.reduce((acc, s) => acc + (s.metadata.lineCount || 0), 0);
      findings.push({
        id: randomUUID(),
        type: 'recommendation',
        title: `Review ${sources.length} analyzed sources (${totalLines} lines)`,
        description: `Inspected sources: ${sourceNames}. Recommended next action: review discovered tasks and confirmed decisions.`,
        sourcePath: sources[0]?.originalPath || 'Workspace',
        sourceName: sources[0]?.displayName || 'Project',
        sourceExcerpt: `Analyzed sources: ${sourceNames}`,
        evidenceClassification: 'directly_observed',
        confidence: 0.95,
        status: 'suggested',
        targetMemoryType: 'task',
        createdAt: Date.now(),
        updatedAt: Date.now()
      });
    }

    return {
      overview: `Analyzed ${sources.length} sources (${sourceNames}) using local intelligence engine. Extracted explicit action items, decisions, and structural indicators.`,
      findings
    };
  }
}

import { dialog, ipcMain } from 'electron';
import { resolve } from 'node:path';
import { ProjectIntelligenceAnalyzer } from './analyzer.ts';
import { inspectSourceItem } from './adapters.ts';
import type { Finding, IntelligenceRunOptions, SourceItem } from './types.ts';
import type { MemoryStore } from '../memory/store.ts';

export * from './types.ts';
export * from './adapters.ts';
export * from './analyzer.ts';

export class IntelligenceController {
  private analyzer: ProjectIntelligenceAnalyzer;
  private approvedAnalysisPaths: Set<string> = new Set();

  constructor(
    private memoryStore: MemoryStore,
    private getIndexedChunks: () => Array<{ id: string; path: string; relativePath: string; name: string; text: string }>,
    private getActiveModel: () => string,
    private broadcast: (channel: string, payload: unknown) => void
  ) {
    this.analyzer = new ProjectIntelligenceAnalyzer();
  }

  public registerIpcHandlers(): void {
    ipcMain.handle('intelligence:choose-files', async () => {
      const res = await dialog.showOpenDialog({
        properties: ['openFile', 'multiSelections'],
        title: 'Select documents, code, notes, or images to analyze'
      });
      if (res.canceled) return [];
      for (const p of res.filePaths) {
        this.approvedAnalysisPaths.add(resolve(p));
      }
      return res.filePaths;
    });

    ipcMain.handle('intelligence:choose-folders', async () => {
      const res = await dialog.showOpenDialog({
        properties: ['openDirectory', 'multiSelections'],
        title: 'Select folder or project directory to analyze'
      });
      if (res.canceled) return [];
      for (const p of res.filePaths) {
        this.approvedAnalysisPaths.add(resolve(p));
      }
      return res.filePaths;
    });

    ipcMain.handle('intelligence:inspect-sources', async (_event, paths: string[]) => {
      if (!Array.isArray(paths)) throw new Error('Paths must be an array.');
      const items: SourceItem[] = [];
      for (const p of paths.slice(0, 100)) {
        if (typeof p === 'string' && p.trim()) {
          items.push(await inspectSourceItem(p));
        }
      }
      return items;
    });

    ipcMain.handle('intelligence:run-analysis', async (_event, options: IntelligenceRunOptions) => {
      if (!options || !Array.isArray(options.sources) || options.sources.length === 0) {
        throw new Error('Please select at least one source file, folder, or indexed library to analyze.');
      }

      return this.analyzer.runAnalysis(options, {
        activeModel: this.getActiveModel(),
        indexedChunks: this.getIndexedChunks(),
        onProgress: p => {
          this.broadcast('intelligence:progress', p);
        }
      });
    });

    ipcMain.handle('intelligence:cancel-analysis', async () => {
      this.analyzer.cancel();
      return true;
    });

    ipcMain.handle('intelligence:accept-finding', async (_event, payload: {
      finding: Finding;
      targetType: 'task' | 'decision';
      editedTitle?: string;
      editedDetails?: string;
      dueDate?: string;
    }) => {
      if (!payload?.finding) {
        throw new Error('Invalid finding data.');
      }

      const f = payload.finding;
      const title = (payload.editedTitle || f.title).trim();
      const details = (payload.editedDetails || f.description || f.reason || '').trim();
      const targetType = payload.targetType || (f.type === 'decision' ? 'decision' : 'task');

      // Create item in persistent MemoryStore
      const memoryItem = await this.memoryStore.createManualItem({
        type: targetType,
        title,
        details: details || undefined,
        sourcePath: f.sourcePath,
        relativePath: f.sourceName,
        sourceExcerpt: f.sourceExcerpt,
        dueDate: payload.dueDate || f.dueDate,
        status: 'open'
      });

      return { success: true, memoryItem };
    });
  }
}

