/* Universal Project Intelligence Styles */
.intel-workspace {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.intel-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.intel-section-title h3 {
  font: 600 13px Manrope, sans-serif;
  color: #d1d8e6;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.sources-action-bar {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}
.sources-panel {
  background: #11141c;
  border: 1px solid #232836;
  border-radius: 12px;
  padding: 16px;
}
.sources-empty-box {
  padding: 24px 16px;
  border: 1px dashed #293040;
  border-radius: 9px;
  text-align: center;
  background: #0d1017;
  color: #8892a4;
  font-size: 11px;
  line-height: 1.6;
}
.sources-chips-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.source-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #151924;
  border: 1px solid #283042;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 11px;
  color: #e1e7f3;
  max-width: 100%;
}
.source-chip-name {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}
.source-type-pill {
  font: 8px 'DM Mono', monospace;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 4px;
  background: #1e2433;
  color: #9cb3e2;
  border: 1px solid #2f3b54;
}
.source-type-pill.unsupported {
  background: #331f18;
  color: #f7a278;
  border-color: #593120;
}
.source-type-pill.pdf {
  background: #331920;
  color: #f799aa;
  border-color: #5a2835;
}
.source-type-pill.image {
  background: #1f3028;
  color: #8ce4b7;
  border-color: #2e523e;
}
.source-type-pill.folder {
  background: #252438;
  color: #bda9ff;
  border-color: #403b66;
}
.chip-remove-btn {
  border: 0;
  background: transparent;
  color: #7b8699;
  padding: 2px;
  display: grid;
  place-items: center;
  cursor: pointer;
  border-radius: 4px;
}
.chip-remove-btn:hover {
  color: #f0a3aa;
  background: #291b1e;
}
.source-warning-box {
  margin-top: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  background: #261912;
  border: 1px solid #523120;
  color: #f5b28a;
  font-size: 11px;
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.goals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 10px;
}
.goal-card {
  background: #11141c;
  border: 1px solid #232836;
  border-radius: 10px;
  padding: 14px 15px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  text-align: left;
}
.goal-card:hover {
  border-color: #384257;
  background: #141822;
}
.goal-card.active {
  border-color: #3b7355;
  background: radial-gradient(ellipse at top left, #16281e 0, #11141c 70%);
}
.goal-card-top {
  display: flex;
  align-items: center;
  gap: 9px;
}
.goal-card-icon {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  background: #1c2230;
  color: #8da4ff;
  flex-shrink: 0;
}
.goal-card.active .goal-card-icon {
  background: #1d3a2b;
  color: #92e2b3;
}
.goal-card-title {
  font: 600 12px Manrope, sans-serif;
  color: #e5eaf3;
  margin: 0;
}
.goal-card-desc {
  font-size: 10px;
  color: #858e9f;
  margin: 0;
  line-height: 1.45;
}
.custom-instructions-wrap {
  margin-top: 14px;
}
.custom-instructions-wrap label {
  display: block;
  font: 10px 'DM Mono', monospace;
  color: #8a96aa;
  margin-bottom: 6px;
}
.custom-instructions-wrap textarea {
  width: 100%;
  min-height: 60px;
  background: #0d1017;
  border: 1px solid #262c3b;
  border-radius: 8px;
  padding: 10px 12px;
  color: #e5ebf5;
  font-size: 11px;
  line-height: 1.5;
  outline: none;
  resize: vertical;
}
.custom-instructions-wrap textarea:focus {
  border-color: #4c6288;
}
.intel-results-wrap {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 10px;
}
.intel-overview-card {
  background: #11151f;
  border: 1px solid #273144;
  border-radius: 12px;
  padding: 20px;
  background: radial-gradient(ellipse at 15% 0%, #15272b 0, #11151f 55%);
}
.intel-overview-card h3 {
  font: 600 15px Manrope, sans-serif;
  color: #e4eaf4;
  margin: 0 0 10px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.intel-overview-card p {
  font-size: 12px;
  line-height: 1.7;
  color: #a8b3c7;
  margin: 0 0 14px;
  white-space: pre-wrap;
}
.intel-overview-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font: 10px 'DM Mono', monospace;
  color: #79859b;
  border-top: 1px solid #202636;
  padding-top: 12px;
  flex-wrap: wrap;
}
.evidence-pill {
  font: 8px 'DM Mono', monospace;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 3px 6px;
  border-radius: 4px;
}
.evidence-pill.explicitly_stated {
  background: #162a1f;
  color: #8be4b2;
  border: 1px solid #275239;
}
.evidence-pill.directly_observed {
  background: #152438;
  color: #90b8ff;
  border: 1px solid #24426d;
}
.evidence-pill.inferred {
  background: #2a1a3d;
  color: #d19fff;
  border: 1px solid #4f2d74;
}
.evidence-pill.suggested {
  background: #20242f;
  color: #9da6b7;
  border: 1px solid #323a4b;
}
.finding-type-pill {
  font: 9px 'DM Mono', monospace;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 7px;
  border-radius: 4px;
}
.finding-type-pill.task {
  background: #14243b;
  color: #92b8ff;
  border: 1px solid #27436f;
}
.finding-type-pill.decision {
  background: #2b193d;
  color: #d2a4ff;
  border: 1px solid #502e75;
}
.finding-type-pill.issue {
  background: #33191c;
  color: #f799a4;
  border: 1px solid #59252c;
}
.finding-type-pill.recommendation {
  background: #132b2b;
  color: #86e4e4;
  border: 1px solid #254f4f;
}
.finding-type-pill.question {
  background: #332612;
  color: #ffd27a;
  border: 1px solid #573e18;
}
.finding-accepted-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: 10px 'DM Mono', monospace;
  color: #8be3b1;
  background: #15291e;
  border: 1px solid #264e37;
  padding: 4px 8px;
  border-radius: 5px;
}

