356:   const MAX_FOLDER_FILES = 400; // Limit to 400 files per single folder analysis to maintain responsiveness
357: 
358:   while (stack.length > 0 && results.length < MAX_FOLDER_FILES) {
359:     const current = stack.pop()!;
360:     let entries;
361:     try {
362:       entries = await fs.readdir(current, { withFileTypes: true });
363:     } catch {
364:       continue;
365:     }
