export type ClipboardContentType = 'code' | 'command' | 'url' | 'json' | 'text';

export interface ClipboardItem {
  id: string;
  text: string;
  capturedAt: number;
  contentHash: string;
  charCount: number;
  lineCount: number;
  contentType: ClipboardContentType;
  isPinned: boolean;
  label?: string;
  sourceApp?: string;
  embedding?: number[];
}

export interface ClipboardSettings {
  enabled: boolean;
  paused: boolean;
  pollIntervalMs: number;
  minCharLength: number;
  maxCharLength: number;
  retentionLimit: number;
  ignoredApps: string[];
  filterSensitiveData: boolean;
}

export interface ClipboardFilter {
  query?: string;
  pinnedOnly?: boolean;
  contentType?: ClipboardContentType | 'all';
  limit?: number;
}

export interface ClipboardSearchResult {
  item: ClipboardItem;
  score: number;
  matchReason: 'exact' | 'keyword' | 'semantic';
}

import { createHash } from 'node:crypto';
import type { ClipboardContentType } from './types.ts';

// Conservative sensitive patterns: API keys, tokens, credentials, private keys
const SENSITIVE_PATTERNS: Array<{ name: string; regex: RegExp }> = [
  // Private keys
  { name: 'Private Key Header', regex: /-----BEGIN\s+([A-Z\s]+)?PRIVATE\s+KEY-----/i },
  { name: 'OpenSSH Private Key', regex: /-----BEGIN\s+OPENSSH\s+PRIVATE\s+KEY-----/i },
  { name: 'RSA Private Key', regex: /-----BEGIN\s+RSA\s+PRIVATE\s+KEY-----/i },

  // Specific known API keys & Tokens
  { name: 'OpenAI API Key', regex: /\bsk-[a-zA-Z0-9_-]{20,}\b/ },
  { name: 'GitHub Classic Token', regex: /\bghp_[a-zA-Z0-9]{36}\b/ },
  { name: 'GitHub Fine-Grained Token', regex: /\bgithub_pat_[a-zA-Z0-9_]{50,}\b/ },
  { name: 'AWS Access Key ID', regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: 'Stripe Secret Key', regex: /\bsk_live_[0-9a-zA-Z]{24,}\b/ },
  { name: 'Slack Bot Token', regex: /\bxox[baprs]-[0-9a-zA-Z-]{10,}\b/ },
  { name: 'Google API Key', regex: /\bAIza[0-9A-Za-z\-_]{35}\b/ },

  // High-entropy bearer tokens & JWTs
  { name: 'JSON Web Token (JWT)', regex: /\beyJ[a-zA-Z0-9_-]{10,}\.eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\b/ },
  { name: 'Authorization Bearer Header', regex: /\bBearer\s+[a-zA-Z0-9\-._~+/]{25,}=*\b/i },

  // Database connection strings containing user:password@host
  { name: 'Database Connection URI with Password', regex: /\b(?:mongodb(?:\+srv)?|postgres(?:ql)?|mysql|redis):\/\/[^:\s]+:[^@\s]+@[^\s/]+/i },

  // Common password or secret assignments in config/env
  { name: 'Password assignment', regex: /(?:^|[\r\n;&|])\s*(?:password|passwd|secret|api_key|access_token)\s*[:=]\s*["']?[^\s"']{8,}["']?/i }
];

export function isSensitiveText(text: string): { isSensitive: boolean; reason?: string } {
  if (!text || text.trim().length === 0) {
    return { isSensitive: false };
  }

  for (const pattern of SENSITIVE_PATTERNS) {
    if (pattern.regex.test(text)) {
      return {
        isSensitive: true,
        reason: `Matches sensitive pattern: ${pattern.name}`
      };
    }
  }

  return { isSensitive: false };
}

export function detectContentType(text: string): ClipboardContentType {
  const trimmed = text.trim();

  // 1. URL check
  if (/^https?:\/\/[^\s$.?#].[^\s]*$/i.test(trimmed) && !trimmed.includes('\n')) {
    return 'url';
  }

  // 2. JSON check
  if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
    try {
      JSON.parse(trimmed);
      return 'json';
    } catch {
      // not valid JSON, continue checking
    }
  }

  // 3. Command check (single or multi-line shell command)
  const commandPrefixes = [
    '$ ', 'sudo ', 'npm ', 'pnpm ', 'yarn ', 'git ', 'docker ', 'kubectl ',
    'curl ', 'wget ', 'brew ', 'cargo ', 'ssh ', 'npx ', 'pip ', 'make ',
    'python ', 'node ', 'cat ', 'grep ', 'systemctl '
  ];
  const firstLine = trimmed.split('\n')[0].trim();
  if (commandPrefixes.some(prefix => firstLine.startsWith(prefix))) {
    return 'command';
  }

  // 4. Code check
  const codeIndicators = [
    /\b(function|const|let|var|class|interface|type|import|export|return)\b/,
    /\b(def|elif|lambda|import\s+\w+|from\s+\w+\s+import)\b/,
    /\b(public|private|protected|void|static)\b/,
    /\b(SELECT\s+.*\s+FROM|INSERT\s+INTO|UPDATE\s+.*\s+SET|DELETE\s+FROM)\b/i,
    /=>|\{|\};|<!--|<\/?[\w\d]+>/
  ];
  if (codeIndicators.some(pattern => pattern.test(trimmed))) {
    return 'code';
  }

  return 'text';
}

export function createClipboardHash(text: string): string {
  // Normalize whitespace to prevent trivial duplicates (e.g. trailing newlines)
  const normalized = text.trim().replace(/\r\n/g, '\n');
  return createHash('sha256').update(normalized, 'utf8').digest('hex');
}

import { promises as fs } from 'node:fs';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import type {
  ClipboardContentType,
  ClipboardFilter,
  ClipboardItem,
  ClipboardSearchResult,
  ClipboardSettings
} from './types.ts';
import {
  createClipboardHash,
  detectContentType,
  isSensitiveText
} from './sensitive.ts';

const DEFAULT_SETTINGS: ClipboardSettings = {
  enabled: false,
  paused: false,
  pollIntervalMs: 1000,
  minCharLength: 4,
  maxCharLength: 50000,
  retentionLimit: 200,
  ignoredApps: ['1Password', 'Bitwarden', 'KeePassXC', 'LastPass'],
  filterSensitiveData: true
};

function cosine(a: number[], b: number[]): number {
  let dot = 0, aa = 0, bb = 0;
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    dot += a[i] * b[i];
    aa += a[i] * a[i];
    bb += b[i] * b[i];
  }
  return aa && bb ? dot / (Math.sqrt(aa) * Math.sqrt(bb)) : 0;
}

export class ClipboardStore {
  private itemsFilePath: string;
  private settingsFilePath: string;
  private items: Map<string, ClipboardItem> = new Map();
  private hashes: Map<string, string> = new Map(); // contentHash -> item.id
  private settings: ClipboardSettings = { ...DEFAULT_SETTINGS };
  private loaded = false;

  constructor(storageDir: string) {
    this.itemsFilePath = join(storageDir, 'clipboard-memory-v1.json');
    this.settingsFilePath = join(storageDir, 'clipboard-settings-v1.json');
  }

  public async load(): Promise<void> {
    this.items.clear();
    this.hashes.clear();

    // 1. Load settings
    try {
      const rawSettings = await fs.readFile(this.settingsFilePath, 'utf8');
      const parsedSettings = JSON.parse(rawSettings);
      this.settings = { ...DEFAULT_SETTINGS, ...parsedSettings };
    } catch {
      this.settings = { ...DEFAULT_SETTINGS };
    }

    // 2. Load items
    try {
      const raw = await fs.readFile(this.itemsFilePath, 'utf8');
      const data = JSON.parse(raw);
      const list: ClipboardItem[] = Array.isArray(data) ? data : (Array.isArray(data?.items) ? data.items : []);

      for (const item of list) {
        if (item && typeof item.id === 'string' && typeof item.text === 'string') {
          const hash = item.contentHash || createClipboardHash(item.text);
          const validItem: ClipboardItem = {
            id: item.id,
            text: item.text,
            capturedAt: item.capturedAt || Date.now(),
            contentHash: hash,
            charCount: item.charCount || item.text.length,
            lineCount: item.lineCount || item.text.split('\n').length,
            contentType: item.contentType || detectContentType(item.text),
            isPinned: Boolean(item.isPinned),
            label: item.label,
            sourceApp: item.sourceApp,
            embedding: item.embedding
          };
          this.items.set(validItem.id, validItem);
          this.hashes.set(hash, validItem.id);
        }
      }
    } catch (err: any) {
      if (err.code !== 'ENOENT') {
        console.warn('Failed to load clipboard store; starting empty:', err);
      }
    }

    this.loaded = true;
  }

  public async save(): Promise<void> {
    const list = Array.from(this.items.values()).sort((a, b) => {
      // Pinned first, then newest capturedAt
      if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
      return b.capturedAt - a.capturedAt;
    });

    const tempItems = `${this.itemsFilePath}.tmp.${Date.now()}`;
    await fs.writeFile(tempItems, JSON.stringify({ version: 1, items: list }, null, 2), 'utf8');
    await fs.rename(tempItems, this.itemsFilePath);

    const tempSettings = `${this.settingsFilePath}.tmp.${Date.now()}`;
    await fs.writeFile(tempSettings, JSON.stringify(this.settings, null, 2), 'utf8');
    await fs.rename(tempSettings, this.settingsFilePath);
  }

  public getSettings(): ClipboardSettings {
    return { ...this.settings };
  }

  public async updateSettings(updates: Partial<ClipboardSettings>): Promise<ClipboardSettings> {
    this.settings = { ...this.settings, ...updates };
    await this.save();
    return { ...this.settings };
  }

  public async addItem(
    text: string,
    metadata?: { sourceApp?: string; label?: string }
  ): Promise<{ item: ClipboardItem | null; status: 'added' | 'duplicate_updated' | 'filtered' }> {
    const trimmed = text.trim();
    if (trimmed.length < this.settings.minCharLength || text.length > this.settings.maxCharLength) {
      return { item: null, status: 'filtered' };
    }

    if (this.settings.filterSensitiveData) {
      const { isSensitive } = isSensitiveText(text);
      if (isSensitive) {
        return { item: null, status: 'filtered' };
      }
    }

    const hash = createClipboardHash(text);
    const existingId = this.hashes.get(hash);

    if (existingId && this.items.has(existingId)) {
      const existing = this.items.get(existingId)!;
      existing.capturedAt = Date.now();
      if (metadata?.sourceApp) existing.sourceApp = metadata.sourceApp;
      if (metadata?.label) existing.label = metadata.label;
      await this.save();
      return { item: { ...existing }, status: 'duplicate_updated' };
    }

    const lines = text.split('\n');
    const newItem: ClipboardItem = {
      id: randomUUID(),
      text,
      capturedAt: Date.now(),
      contentHash: hash,
      charCount: text.length,
      lineCount: lines.length,
      contentType: detectContentType(text),
      isPinned: false,
      label: metadata?.label,
      sourceApp: metadata?.sourceApp
    };

    this.items.set(newItem.id, newItem);
    this.hashes.set(hash, newItem.id);

    // Enforce retention limit (pinned items are protected from eviction)
    this.enforceRetentionLimit();

    await this.save();
    return { item: { ...newItem }, status: 'added' };
  }

  private enforceRetentionLimit(): void {
    const limit = Math.max(10, this.settings.retentionLimit || 200);
    const total = this.items.size;
    if (total <= limit) return;

    // Separate pinned from unpinned
    const unpinned: ClipboardItem[] = [];
    for (const item of this.items.values()) {
      if (!item.isPinned) unpinned.push(item);
    }

    // Sort unpinned by capturedAt ascending (oldest first)
    unpinned.sort((a, b) => a.capturedAt - b.capturedAt);

    const toRemoveCount = total - limit;
    for (let i = 0; i < Math.min(toRemoveCount, unpinned.length); i++) {
      const target = unpinned[i];
      this.items.delete(target.id);
      this.hashes.delete(target.contentHash);
    }
  }

  public listItems(filter?: ClipboardFilter): ClipboardItem[] {
    let list = Array.from(this.items.values());

    if (filter?.pinnedOnly) {
      list = list.filter(i => i.isPinned);
    }

    if (filter?.contentType && filter.contentType !== 'all') {
      list = list.filter(i => i.contentType === filter.contentType);
    }

    list.sort((a, b) => {
      if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
      return b.capturedAt - a.capturedAt;
    });

    if (filter?.limit && filter.limit > 0) {
      return list.slice(0, filter.limit);
    }

    return list;
  }

  public search(
    query: string,
    options?: {
      pinnedOnly?: boolean;
      contentType?: ClipboardContentType | 'all';
      queryEmbedding?: number[];
      limit?: number;
    }
  ): ClipboardSearchResult[] {
    const q = (query || '').trim().toLowerCase();
    const queryWords = q.split(/\s+/).filter(w => w.length > 1);
    const maxResults = options?.limit || 50;

    let candidates = Array.from(this.items.values());

    if (options?.pinnedOnly) {
      candidates = candidates.filter(i => i.isPinned);
    }

    if (options?.contentType && options.contentType !== 'all') {
      candidates = candidates.filter(i => i.contentType === options.contentType);
    }

    // If query is empty, return recent items
    if (!q) {
      return candidates
        .sort((a, b) => {
          if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
          return b.capturedAt - a.capturedAt;
        })
        .slice(0, maxResults)
        .map(item => ({ item, score: 1, matchReason: 'exact' }));
    }

    const scored: ClipboardSearchResult[] = [];

    for (const item of candidates) {
      const textLower = item.text.toLowerCase();
      const labelLower = (item.label || '').toLowerCase();
      let lexicalScore = 0;
      let matchReason: 'exact' | 'keyword' | 'semantic' = 'keyword';

      // Exact substring match has high priority
      if (textLower.includes(q) || labelLower.includes(q)) {
        lexicalScore += 2.0;
        matchReason = 'exact';
      }

      // Individual keyword match
      if (queryWords.length > 0) {
        let matchedWords = 0;
        for (const w of queryWords) {
          if (textLower.includes(w) || labelLower.includes(w)) {
            matchedWords++;
          }
        }
        lexicalScore += (matchedWords / queryWords.length);
      }

      // Optional semantic score if embeddings are available
      let semanticScore = 0;
      if (options?.queryEmbedding && item.embedding && item.embedding.length > 0) {
        semanticScore = cosine(options.queryEmbedding, item.embedding);
        if (semanticScore > 0.65 && matchReason !== 'exact') {
          matchReason = 'semantic';
        }
      }

      // Combined score: lexical weighted + semantic weighted
      const combinedScore = (lexicalScore * 0.7) + (semanticScore * 0.3);

      if (lexicalScore > 0 || semanticScore > 0.6) {
        scored.push({
          item,
          score: combinedScore,
          matchReason
        });
      }
    }

    // Sort by score descending; if tied, pinned items first, then newer items
    scored.sort((a, b) => {
      if (Math.abs(a.score - b.score) > 0.05) return b.score - a.score;
      if (a.item.isPinned !== b.item.isPinned) return a.item.isPinned ? -1 : 1;
      return b.item.capturedAt - a.item.capturedAt;
    });

    return scored.slice(0, maxResults);
  }

  public async pinItem(id: string, isPinned: boolean): Promise<ClipboardItem | null> {
    const item = this.items.get(id);
    if (!item) return null;
    item.isPinned = isPinned;
    await this.save();
    return { ...item };
  }

  public async setLabel(id: string, label: string): Promise<ClipboardItem | null> {
    const item = this.items.get(id);
    if (!item) return null;
    item.label = label.trim() || undefined;
    await this.save();
    return { ...item };
  }

  public async deleteItem(id: string): Promise<boolean> {
    const item = this.items.get(id);
    if (!item) return false;
    this.items.delete(id);
    this.hashes.delete(item.contentHash);
    await this.save();
    return true;
  }

  public async clearHistory(preservePinned = true): Promise<number> {
    let clearedCount = 0;
    const toDelete: string[] = [];

    for (const [id, item] of this.items.entries()) {
      if (preservePinned && item.isPinned) continue;
      toDelete.push(id);
    }

    for (const id of toDelete) {
      const item = this.items.get(id);
      if (item) {
        this.hashes.delete(item.contentHash);
        this.items.delete(id);
        clearedCount++;
      }
    }

    await this.save();
    return clearedCount;
  }

  public getItem(id: string): ClipboardItem | null {
    const item = this.items.get(id);
    return item ? { ...item } : null;
  }

  public getUnembeddedItems(limit = 20): ClipboardItem[] {
    const result: ClipboardItem[] = [];
    for (const item of this.items.values()) {
      if (!item.embedding || item.embedding.length === 0) {
        result.push(item);
        if (result.length >= limit) break;
      }
    }
    return result;
  }

  public async setItemEmbedding(id: string, embedding: number[]): Promise<void> {
    const item = this.items.get(id);
    if (item) {
      item.embedding = embedding;
      await this.save();
    }
  }
}

import { clipboard } from 'electron';
import type { ClipboardItem, ClipboardSettings } from './types.ts';
import { ClipboardStore } from './store.ts';
import { createClipboardHash } from './sensitive.ts';

export class ClipboardService {
  private store: ClipboardStore;
  private pollTimer: NodeJS.Timeout | null = null;
  private lastCapturedHash: string | null = null;
  private isPolling = false;
  private onCaptured?: (item: ClipboardItem, status: 'added' | 'duplicate_updated') => void;

  constructor(
    store: ClipboardStore,
    onCaptured?: (item: ClipboardItem, status: 'added' | 'duplicate_updated') => void
  ) {
    this.store = store;
    this.onCaptured = onCaptured;
  }

  public get isRunning(): boolean {
    return this.pollTimer !== null;
  }

  public start(): void {
    const settings = this.store.getSettings();
    if (!settings.enabled || settings.paused) {
      return;
    }

    if (this.pollTimer) {
      return; // Already polling
    }

    // Initialize lastCapturedHash with current clipboard text so we don't retroactively
    // capture text that was in the clipboard before enabling the feature!
    try {
      const initialText = clipboard.readText();
      if (initialText && initialText.trim()) {
        this.lastCapturedHash = createClipboardHash(initialText);
      }
    } catch {
      this.lastCapturedHash = null;
    }

    const interval = Math.max(500, settings.pollIntervalMs || 1000);
    this.pollTimer = setInterval(() => this.poll(), interval);
  }

  public stop(): void {
    if (this.pollTimer) {
      clearInterval(this.pollTimer);
      this.pollTimer = null;
    }
    this.lastCapturedHash = null;
  }

  public pause(): void {
    this.stop();
  }

  public resume(): void {
    this.start();
  }

  private async poll(): Promise<void> {
    if (this.isPolling) return;
    this.isPolling = true;

    try {
      const text = clipboard.readText();
      if (!text || text.trim().length === 0) {
        return;
      }

      const currentHash = createClipboardHash(text);
      if (currentHash === this.lastCapturedHash) {
        return; // Content hasn't changed
      }

      this.lastCapturedHash = currentHash;

      // Add to store (handles length bounds, sensitive filtering, and retention)
      const res = await this.store.addItem(text);
      if (res.item && (res.status === 'added' || res.status === 'duplicate_updated')) {
        this.onCaptured?.(res.item, res.status);
      }
    } catch (err: any) {
      // Do not log clipboard contents in error logs
      console.warn('Clipboard read error in monitoring service:', err?.message || String(err));
    } finally {
      this.isPolling = false;
    }
  }

  public copyToClipboard(text: string): void {
    try {
      // Temporarily mark this hash as seen so we don't re-capture text
      // that was copied FROM RecallDesk itself!
      this.lastCapturedHash = createClipboardHash(text);
      clipboard.writeText(text);
    } catch (err: any) {
      console.error('Failed to write to clipboard:', err?.message || String(err));
      throw new Error('Failed to copy text to system clipboard.');
    }
  }
}

import { ipcMain } from 'electron';
import { ClipboardStore } from './store.ts';
import { ClipboardService } from './service.ts';
import type { ClipboardContentType, ClipboardFilter, ClipboardSettings } from './types.ts';

export class ClipboardController {
  private store: ClipboardStore;
  private service: ClipboardService;
  private getEmbedder?: () => Promise<any>;
  private broadcast: (channel: string, payload: unknown) => void;

  constructor(
    storageDir: string,
    broadcast: (channel: string, payload: unknown) => void,
    getEmbedder?: () => Promise<any>
  ) {
    this.store = new ClipboardStore(storageDir);
    this.broadcast = broadcast;
    this.getEmbedder = getEmbedder;
    this.service = new ClipboardService(this.store, (item, status) => {
      this.broadcast('clipboard:item-captured', { item, status });
      // Background embedding generation if embedder is available
      this.maybeEmbedItem(item.id, item.text).catch(() => {});
    });
  }

  public async init(): Promise<void> {
    await this.store.load();
    const settings = this.store.getSettings();
    if (settings.enabled && !settings.paused) {
      this.service.start();
    }
  }

  public stopService(): void {
    this.service.stop();
  }

  public getStore(): ClipboardStore {
    return this.store;
  }

  private async maybeEmbedItem(id: string, text: string): Promise<void> {
    if (!this.getEmbedder) return;
    try {
      const model = await this.getEmbedder();
      if (!model) return;
      const snippet = text.slice(0, 500); // Embed first 500 characters
      const out = await model(snippet, { pooling: 'mean', normalize: true });
      const embedding = Array.from(out.data as Float32Array);
      await this.store.setItemEmbedding(id, embedding);
    } catch {
      // Embedding failure is non-fatal; keyword search remains active
    }
  }

  public registerIpcHandlers(): void {
    ipcMain.handle('clipboard:get-settings', async () => {
      return this.store.getSettings();
    });

    ipcMain.handle('clipboard:update-settings', async (_event, updates: Partial<ClipboardSettings>) => {
      if (!updates || typeof updates !== 'object') {
        throw new Error('Invalid clipboard settings updates.');
      }
      const updated = await this.store.updateSettings(updates);
      if (updated.enabled && !updated.paused) {
        this.service.start();
      } else {
        this.service.stop();
      }
      return updated;
    });

    ipcMain.handle('clipboard:list-items', async (_event, filter?: ClipboardFilter) => {
      return this.store.listItems(filter);
    });

    ipcMain.handle('clipboard:search', async (_event, query: string, options?: {
      pinnedOnly?: boolean;
      contentType?: ClipboardContentType | 'all';
      limit?: number;
    }) => {
      if (typeof query !== 'string') query = '';

      let queryEmbedding: number[] | undefined;
      if (query.trim() && this.getEmbedder) {
        try {
          const model = await this.getEmbedder();
          if (model) {
            const out = await model(query.trim(), { pooling: 'mean', normalize: true });
            queryEmbedding = Array.from(out.data as Float32Array);
          }
        } catch {
          // Fall back gracefully to keyword search
        }
      }

      return this.store.search(query, {
        ...options,
        queryEmbedding
      });
    });

    ipcMain.handle('clipboard:copy-item', async (_event, id: string) => {
      if (typeof id !== 'string') throw new Error('Invalid item ID.');
      const item = this.store.getItem(id);
      if (!item) throw new Error('Clipboard entry not found.');
      this.service.copyToClipboard(item.text);
      return { success: true };
    });

    ipcMain.handle('clipboard:pin-item', async (_event, id: string, isPinned: boolean) => {
      if (typeof id !== 'string') throw new Error('Invalid item ID.');
      const updated = await this.store.pinItem(id, Boolean(isPinned));
      if (!updated) throw new Error('Clipboard entry not found.');
      return updated;
    });

    ipcMain.handle('clipboard:set-label', async (_event, id: string, label: string) => {
      if (typeof id !== 'string') throw new Error('Invalid item ID.');
      const updated = await this.store.setLabel(id, typeof label === 'string' ? label : '');
      if (!updated) throw new Error('Clipboard entry not found.');
      return updated;
    });

    ipcMain.handle('clipboard:delete-item', async (_event, id: string) => {
      if (typeof id !== 'string') throw new Error('Invalid item ID.');
      return this.store.deleteItem(id);
    });

    ipcMain.handle('clipboard:clear-history', async (_event, preservePinned?: boolean) => {
      return this.store.clearHistory(preservePinned !== false);
    });
  }
}

