.finding-accepted-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: 10px 'DM Mono', monospace;
  color: #8be3b1;
  background: #15291e;
  border: 1px solid #264e37;
  padding: 4px 8px;
  border-radius: 5px;
