/* Clipboard Memory Styles */
.clipboard-nav-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #84e5aa;
  box-shadow: 0 0 8px #84e5aa88;
  margin-left: auto;
  animation: pulse-dot 2s infinite ease-in-out;
}
@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.85); }
}

.clipboard-container {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.clipboard-status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  background: #11151e;
  border: 1px solid #232938;
  border-radius: 12px;
  gap: 15px;
  flex-wrap: wrap;
}

.clipboard-status-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.clipboard-state-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px;
  border-radius: 6px;
  font: 11px 'DM Mono', monospace;
  letter-spacing: 0.3px;
  font-weight: 500;
}
.clipboard-state-badge.active {
  background: #13271c;
  color: #89e4ad;
  border: 1px solid #265038;
}
.clipboard-state-badge.paused {
  background: #2b2112;
  color: #ffd175;
  border: 1px solid #573e1c;
}
.clipboard-state-badge.disabled {
  background: #20242f;
  color: #9aa3b4;
  border: 1px solid #303746;
}

.clipboard-privacy-hero {
  border: 1px solid #27382d;
  background: radial-gradient(ellipse at 15% 0%, #173224 0%, transparent 60%), #11141c;
  border-radius: 14px;
  padding: 32px 30px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}

.clipboard-hero-top {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 20px;
}

.clipboard-hero-icon {
  width: 48px;
  height: 48px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #1b3d2b, #2b5c42);
  color: #9ce8bd;
  box-shadow: 0 6px 20px rgba(156, 232, 189, 0.15);
}

.clipboard-hero-title h2 {
  font: 700 22px Manrope, sans-serif;
