.clipboard-copy-btn.copied {
  background: #173523;
  color: #9ce8bd;
  border-color: #2a5a3a;
}

/* Daily Memory Briefing Styles */
.briefing-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}
.briefing-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.briefing-scope-select {
  display: flex;
  align-items: center;
  gap: 7px;
  background: #151923;
  border: 1px solid #282f3e;
  border-radius: 8px;
  padding: 8px 12px;
  color: #cdd5e2;
  font-size: 11px;
}
.briefing-scope-select select {
  background: transparent;
  border: 0;
  outline: 0;
  color: #cdd5e2;
  font-size: 11px;
  cursor: pointer;
}
.briefing-scope-select select option {
  background: #151923;
  color: #cdd5e2;
}

.briefing-meta-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #11151e;
  border: 1px solid #222938;
  border-radius: 10px;
  padding: 12px 16px;
  margin-bottom: 18px;
  font-size: 11px;
  color: #9aa4b7;
}
.briefing-meta-left {
  display: flex;
  align-items: center;
  gap: 12px;
}
.briefing-meta-date {
  font-weight: 600;
  color: #e5ebf5;
  display: flex;
  align-items: center;
  gap: 6px;
}
.briefing-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 6px;
  letter-spacing: 0.3px;
}
.briefing-badge.ai {
  background: #231b38;
  color: #c9b4ff;
  border: 1px solid #45346e;
}
.briefing-badge.deterministic {
  background: #12281e;
  color: #9ce8bd;
  border: 1px solid #244b37;
}

.briefing-summary-card {
  background: radial-gradient(ellipse at 15% 0%, #173224 0%, transparent 60%), #11151e;
  border: 1px solid #28372f;
  border-radius: 12px;
  padding: 22px 24px;
  margin-bottom: 24px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
}
.briefing-summary-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-family: 'DM Mono', monospace;
  letter-spacing: 1.2px;
  color: #9ce8bd;
  margin-bottom: 10px;
  text-transform: uppercase;
}
.briefing-summary-text {
  font-size: 14px;
  line-height: 1.65;
  color: #e4eaf4;
  margin: 0;
  font-weight: 500;
}
.briefing-insufficient-banner {
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: #2a2214;
  border: 1px solid #554121;
  color: #f7d58b;
  padding: 9px 12px;
  border-radius: 8px;
  font-size: 11px;
}

.briefing-focus-section {
  margin-bottom: 26px;
}
.briefing-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.briefing-section-heading h3 {
  font: 600 15px Manrope, sans-serif;
  color: #e1e7f3;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.briefing-section-heading span {
  font-size: 11px;
  color: #7d8799;
}

.focus-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px;
}
.focus-card {
  background: #131722;
  border: 1px solid #232a3a;
  border-radius: 11px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  transition: transform 0.15s, border-color 0.15s;
}
.focus-card:hover {
  transform: translateY(-2px);
  border-color: #38455d;
}
.focus-card.priority-high {
  border-left: 3px solid #ff7b88;
}
.focus-card.priority-medium {
  border-left: 3px solid #f6c466;
}
.focus-card.priority-low {
  border-left: 3px solid #9ce8bd;
}
.focus-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.focus-priority-pill {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  padding: 3px 6px;
  border-radius: 4px;
}
.priority-high .focus-priority-pill {
  background: #33171c;
  color: #ff9da6;
  border: 1px solid #5e232c;
}
.priority-medium .focus-priority-pill {
  background: #2b2113;
  color: #f7d488;
  border: 1px solid #543f1e;
}
.priority-low .focus-priority-pill {
  background: #13241b;
  color: #9ce8bd;
  border: 1px solid #244935;
}
.focus-card h4 {
  font: 600 13px Manrope, sans-serif;
  color: #f0f4fc;
  margin: 0 0 8px;
  line-height: 1.4;
}
.focus-rationale {
  font-size: 11px;
  color: #8c96a8;
  line-height: 1.55;
  margin: 0 0 14px;
  flex: 1;
}
.focus-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  border-top: 1px solid #1c2230;
  padding-top: 11px;
  margin-top: auto;
}
.focus-btn {
  font-size: 10px;
  font-weight: 600;
  color: #9ce8bd;
  background: #16261d;
  border: 1px solid #284734;
  padding: 5px 9px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: all 0.15s;
}
.focus-btn:hover {
  background: #1e3a2b;
  color: #bbf0d2;
}

.briefing-columns {
  display: grid;
  grid-template-columns: 1.25fr 0.75fr;
  gap: 20px;
}
.briefing-column {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.briefing-block {
  background: #11141c;
  border: 1px solid #232937;
  border-radius: 12px;
  padding: 18px 20px;
}
.briefing-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  border-bottom: 1px solid #1f2533;
  padding-bottom: 10px;
}
.briefing-block-header h4 {
  font: 600 13px Manrope, sans-serif;
  color: #dbe2ef;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.briefing-count {
  font-size: 10px;
  font-family: 'DM Mono', monospace;
  background: #1b212f;
  color: #9cb0d8;
  padding: 2px 6px;
  border-radius: 4px;
}

.briefing-task-list,
.briefing-decision-list,
.briefing-activity-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.briefing-task-item {
  display: flex;
  align-items: flex-start;
  gap: 11px;
