args.ReplacementContent:
.history-item-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 4px;
}

/* Nav Dock Section Label */
.nav-section-label {
  margin: 16px 0 6px 12px;
  font-size: 9px;
  font-family: 'DM Mono', monospace;
  color: #647087;
  letter-spacing: 0.9px;
  text-transform: uppercase;
}

/* Daily Audio Briefing Styles */
.briefing-audio-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: linear-gradient(135deg, #131b28 0%, #161e2c 100%);
  border: 1px solid #293852;
  border-radius: 10px;
  padding: 10px 16px;
  margin-bottom: 20px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
}
.audio-info {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  color: #b8c8e6;
}
.audio-wave {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 16px;
}
.wave-bar {
  width: 3px;
  height: 6px;
  background: #9ce8bd;
  border-radius: 2px;
  animation: waveBounce 0.8s ease-in-out infinite alternate;
}
.wave-bar:nth-child(2) { animation-delay: 0.2s; height: 12px; }
.wave-bar:nth-child(3) { animation-delay: 0.4s; height: 16px; }
.wave-bar:nth-child(4) { animation-delay: 0.1s; height: 8px; }
@keyframes waveBounce {
  0% { transform: scaleY(0.4); }
  100% { transform: scaleY(1.3); }
}
.audio-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}
.audio-rate-btn {
  font-size: 10px;
  font-family: 'DM Mono', monospace;
  background: #1d2537;
  border: 1px solid #334260;
  color: #a7b9dc;
  padding: 4px 7px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.15s;
}
.audio-rate-btn.active {
  background: #273b5e;
  color: #dbe7ff;
  border-color: #4b6699;
}

/* Momentum & Readiness Dashboard */
.momentum-dashboard {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 12px;
  margin-bottom: 22px;
}
.momentum-card {
  background: #11151e;
  border: 1px solid #212837;
  border-radius: 11px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: border-color 0.15s, transform 0.15s;
}
.momentum-card:hover {
  border-color: #333e54;
  transform: translateY(-1px);
}
.momentum-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.momentum-icon.score { background: #152c21; color: #7fdfa5; border: 1px solid #244b38; }
.momentum-icon.deadlines { background: #2f171b; color: #ff8892; border: 1px solid #57252c; }
.momentum-icon.focus { background: #1c2237; color: #a6b9ff; border: 1px solid #323e61; }
.momentum-icon.activity { background: #2a2214; color: #f6c466; border: 1px solid #4f3b1b; }
.momentum-info strong {
  display: block;
  font: 700 16px Manrope, sans-serif;
  color: #f1f4fb;
}
.momentum-info span {
  font-size: 10px;
  color: #838e9f;
}

/* Interactive Focus Timer Session Card */
.focus-session-card {
  background: linear-gradient(135deg, #17202e 0%, #10151f 100%);
  border: 1px solid #364868;
  border-radius: 12px;
  padding: 16px 20px;
  margin-bottom: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.35);
}
.focus-session-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.focus-session-clock {
  font-family: 'DM Mono', monospace;
  font-size: 26px;
  font-weight: 700;
  color: #9ce8bd;
  letter-spacing: 1px;
  background: #111a1b;
  border: 1px solid #233b37;
  padding: 6px 14px;
  border-radius: 8px;
}
.focus-session-details h4 {
  margin: 0 0 4px;
  font: 600 13px Manrope, sans-serif;
  color: #e5ecf7;
}
.focus-session-details p {
  margin: 0;
  font-size: 11px;
  color: #8c98ab;
}

/* Daily Intent & Reflection Scratchpad */
.daily-intent-card {
  background: #121620;
  border: 1px solid #232b3a;
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.daily-intent-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 600;
  color: #c9d4e5;
}
.daily-intent-input {
  background: #171c27;
  border: 1px solid #263042;
  border-radius: 7px;
  padding: 9px 12px;
  color: #e5ebf5;
  font-size: 12px;
  outline: none;
  transition: border-color 0.15s;
}
.daily-intent-input:focus {
  border-color: #699c7c;
}

/* Briefing Internal Navigation Tabs */
.briefing-tabs-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #12151e;
  border: 1px solid #222937;
  border-radius: 8px;
  padding: 4px;
  margin-bottom: 20px;
}
.briefing-tab-btn {
  border: 0;
  background: transparent;
  color: #818c9e;
  font-size: 11px;
  font-weight: 500;
  padding: 7px 12px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
  cursor: pointer;
}
.briefing-tab-btn.active {
  background: #1b2332;
  color: #e2e8f4;
}
.briefing-tab-btn:hover {
  color: #cbd5e4;
}

.deadline-pill.overdue {
  background: #42161b;
  border-color: #7a2933;
  color: #ff919a;
}
.deadline-pill.today {
  background: #3e2813;
  border-color: #72471d;
  color: #f7ca78;
}

