  lines.push(`\n*Summary:* ${activeBriefing.summary}`);

  if (activeBriefing.focusItems.length > 0) {
    lines.push(`\n🎯 *Today's Focus Priorities:*`);
    activeBriefing.focusItems.forEach(f => {
